  }, plan = {{name = "Shield Specialization", tree = "Protection", from = 10, to = 14, why = "The talent that makes Protection work in Forever: 5 Rage per block (up from 1 in Classic), guaranteed at 5/5, plus 5% more block. In Defensive Stance your Rage comes from being hit, so this is your engine. Take all five ranks first.", more = "Keep going. Each rank adds 20% to the chance of 5 Rage per block and 1% more block.", max = 5, icon = "inv_shield_06"}, {name = "Improved Thunder Clap", tree = "Protection", from = 15, to = 17, why = "Thunder Clap works in Defensive Stance in Forever and slows attacks by 20% (double Classic) for 10–30 sec by rank. Clap when several mobs reach you. Six Rage off each cast lets you afford it alongside Revenge.", more = "Another 2 Rage off Thunder Clap.", max = 3, icon = "ability_thunderclap"}, {name = "Improved Bloodrage", tree = "Protection", from = 18, to = 19, why = "Bloodrage (10 Rage at once, 10 more over 10 sec, every minute) fires from Fight in combat when it is ready (on the swap back to Defensive, later with your first Sunder). +50% means you can Thunder Clap right after the Charge.", more = "Bloodrage now gives 50% more Rage.", max = 2, icon = "ability_racial_bloodrage"}, {name = "Master of Defense", tree = "Protection", from = 20, to = 21, why = "Needs Shield Specialization 5/5. Dodges and parries now pay 5 Rage too, so together with Shield Specialization every attack you block or avoid feeds you.", more = "Guaranteed 5 Rage on every dodge and parry.", max = 2, icon = "ability_warrior_shieldguard"}, {name = "Improved Revenge", tree = "Protection", from = 22, to = 24, why = "Revenge costs 5 Rage, already hits about 70% harder than in Classic and lights on every block, dodge and parry — and Shield Block helps open a proc when melee attacks are coming. +60% on top makes it your hardest hit until Shield Slam.", more = "More Revenge damage. Finish all three ranks.", max = 3, icon = "ability_warrior_revenge"}, {name = "Vanguard", tree = "Protection", from = 25, to = 25, why = "The first level it can be taken (row 4 needs 15 points). Charge from Defensive Stance: no more stance dance, 9 Rage on an out-of-combat pull (12 from 26 and 15 from 46). Fight can Charge from Defensive while you have Vanguard.", more = "", max = 1, icon = "ability_warrior_shieldcharge"}, {name = "Last Stand", tree = "Protection", from = 26, to = 26, why = "An emergency button for pulls that go wrong: 30% extra max health for 20 sec, every 3 minutes.", more = "", max = 1, icon = "spell_holy_ashestoashes"}, {name = "Defiance", tree = "Protection", from = 27, to = 29, why = "+20% threat in Defensive Stance with a shield, for dungeons and group quests. Since the 2 Nov update Defensive Stance alone gives +80% threat, so solo you will rarely miss it — questing only? Take Anticipation here and buy Defiance back at 54–56.", more = "More threat in Defensive Stance.", max = 3, icon = "ability_warrior_innerrage"}, {name = "Concussion Blow", tree = "Protection", from = 30, to = 30, why = "A 5 sec stun for 10 Rage every 45 sec — stops casters and runners in any stance. It is also the required prerequisite for Shield Slam at 40.", more = "", max = 1, icon = "ability_thunderbolt"}, {name = "Focused Rage", tree = "Protection", from = 31, to = 33, why = "3 Rage off every attack: Sunder, Thunder Clap, Heroic Strike, Cleave, later Shield Slam — and Revenge drops from 5 Rage to 2. Your biggest efficiency jump.", more = "One more Rage off every attack.", max = 3, icon = "ability_warrior_focusedrage"}, {name = "Improved Shield Wall", tree = "Protection", from = 34, to = 34, why = "Bastion (row 6) needs 25 points in Protection — this is the 25th. Useful anyway: Shield Wall comes back in 9.5 min instead of 15.", more = "", max = 2, icon = "ability_warrior_shieldwall"}, {name = "Bastion", tree = "Protection", from = 35, to = 39, why = "Your biggest damage talent: up to +10% to everything you deal while holding a shield, which you always are.", more = "+2% more damage with a shield.", max = 5, icon = "inv_shield_04"}, {name = "Shield Slam", tree = "Protection", from = 40, to = 40, why = "The capstone, open the moment you hit 40 (30 points spent, Concussion Blow taken). 20 Rage, 6 sec cooldown, nearly double Classic's damage plus your shield's Block Value, and very high threat. Use its dedicated button on your kill target or the enemy that needs threat.", more = "", max = 1, icon = "inv_shield_05"}, {name = "Improved Shield Wall", tree = "Protection", from = 41, to = 41, why = "Shield Wall (60% less damage for 12 sec) on a 4-minute cooldown — usable on almost every rough pull.", more = "", max = 2, icon = "ability_warrior_shieldwall"}, {name = "Cruelty", tree = "Fury", from = 42, to = 46, why = "Your key Protection talents are done. +5% crit from the first Fury row is the best damage left for the points.", more = "+1% more crit.", max = 5, icon = "ability_rogue_eviscerate"}, {name = "Deflection", tree = "Arms", from = 47, to = 51, why = "+5% parry from the first Arms row: each parry pays 5 Rage through Master of Defense and lights Revenge. It also opens Improved Charge.", more = "+1% more parry.", max = 5, icon = "ability_parry"}, {name = "Improved Charge", tree = "Arms", from = 52, to = 53, why = "With Vanguard you Charge every pull, so +6 Rage per Charge pays off on every fight.", more = "+3 more Rage per Charge.", max = 2, icon = "ability_warrior_charge"}, {name = "Anticipation", tree = "Protection", from = 54, to = 58, why = "+20 Defense skill: a little more block, dodge and parry (so more Rage and Revenge), and fewer crits taken.", more = "+4 more Defense.", max = 5, icon = "spell_nature_mirrorimage"}, {name = "Improved Sunder Armor", tree = "Protection", from = 59, to = 60, why = "Cheaper Sunder Armor for holding threat in groups. Tanking casters? Improved Shield Bash (silence) is a fine swap.", more = "One more Rage off Sunder Armor.", max = 3, icon = "ability_warrior_sunder"}}, train = {{level = 1, sp