zen targets for 300% more; Shatter (26–28) adds up to 50% crit chance against them. Freeze first, then burst.", steps = {"Frostbolt, Frostbolt as it closes.", "Frost Nova when it reaches you.", "Ice Lance while it's frozen — then Frostbolt again before the ice breaks.", "See ice from a Frostbite proc? Lance it immediately.", "Nova on cooldown and a mob on you: Blink away (LT+Y).", "Packs: Blizzard (20), then Cone of Cold (26) as they arrive.", "Evocation when low on mana instead of sitting to drink.", "Bad pull: Ice Block (29, RT+Left; press again to leave it early), then Blink away."}, stepIcons = {"spell_frost_frostbolt02", "spell_frost_frostnova", "spell_frost_frostblast", "spell_frost_frostarmor", "spell_arcane_blink", "spell_frost_icestorm", "spell_nature_purge", "spell_frost_frost"}}, {level = 30, icon = "ability_mage_wintersgrasp", title = "Fingers of Frost", range = "Levels 30–39", intro = "Fingers of Frost makes your next two spells act as if the target were frozen. Every proc is a free Shatter — no Nova needed.", steps = {"Fingers of Frost lit? Ice Lance, then Frostbolt — both shatter.", "Ice Armor (30) on instead of Frost Armor.", "Cold Snap (34) resets Nova and Ice Block for a second go on hard fights.", "Packs: Get away (Frost Nova), then Pack: Cone of Cold and Arcane Explosions.", "Counterspell healers and casters (24+)."}, stepIcons = {"ability_mage_wintersgrasp", "spell_frost_frostarmor02", "spell_frost_wizardmark", "spell_frost_glacier", "spell_frost_iceshock"}}, {level = 40, icon = "spell_ice_lament", title = "Ice Barrier", range = "Levels 40–60", intro = "Ice Barrier on a 30 sec cooldown absorbs damage and adds 15% Frost damage — 20% while it holds. Keep it up constantly with the Shield up button.", steps = {"Ice Barrier before every pull and whenever it's ready.", "Frostbolt as your filler.", "Nova → Ice Lance → Frostbolt, and Lance on every Fingers of Frost.", "Mana gem first, Evocation second, drinking last.", "Blizzard packs — with Improved Blizzard (48+) its chill can trigger Frostbite freezes. Keep its rank current, or those procs drop."}, stepIcons = {"spell_ice_lament", "spell_frost_frostbolt02", "spell_frost_frostblast", "inv_misc_gem_ruby_01", "spell_frost_icestorm"}}}, spec = "Frost", guide = "Frost Mage"},
