    {name = "Fight", title = "Fight", icon = "ability_whirlwind", lo = 1, hi = 3,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/cast [harm,nodead] !Auto Shot", pad = "RT+A", kb = "1",
     tips = {"Each press: picks the nearest enemy when you have none (or yours died) and starts Auto Shot. Pressing again never turns Auto Shot off.", "Auto Shot only fires past 8 yards. When a mob reaches you, use Too close (LT+Y)."}},
    {name = "Fight", title = "Fight: Serpent pull", icon = "ability_hunter_quickshot", lo = 4, hi = 5,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/cast [harm,nodead] !Auto Shot\n/cast [nocombat,harm,nodead] Serpent Sting", pad = "RT+A", kb = "1",
     tips = {"Out of combat the press also pulls with Serpent Sting. In combat it only keeps Auto Shot going.", "Picks the nearest enemy when you have none or yours died. Mob in your face? Too close (LT+Y)."}},
    {name = "Fight", title = "Fight: Mark, Sting, Arcane", icon = "ability_impalingbolt", lo = 6, hi = 9,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/cast [nocombat,harm,nodead] Hunter's Mark\n/cast [harm,nodead] !Auto Shot\n/castsequence [combat] reset=target Serpent Sting, Arcane Shot, Arcane Shot, Arcane Shot", pad = "RT+A", kb = "1",
     tips = {"Out of combat: Hunter's Mark and Auto Shot, which pulls. In combat: Serpent Sting, then Arcane Shot three times, then Serpent Sting again (about every 20 sec on a long fight).", "\"Not ready\" is Arcane Shot's 6 sec cooldown: Auto Shot keeps firing, press again. A new target starts over at Serpent Sting.", "Picks the nearest enemy when you have none or yours died."}},
    {name = "Fight", title = "Fight: Mark, Sting, Arcane", icon = "ability_impalingbolt", lo = 10, hi = 60,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/petattack [harm,nodead]\n/cast [nocombat,harm,nodead] Hunter's Mark\n/cast [combat][nopet] !Auto Shot\n/castsequence [combat] reset=target Serpent Sting, Arcane Shot, Arcane Shot, Arcane Shot", pad = "RT+A", kb = "1",
     tips = {"Out of combat with your pet out: Hunter's Mark and the pet runs in, no shot yet, so the pet takes the first hit. Press again once it is fighting (you are in combat then): Auto Shot starts.", "In combat: Serpent Sting, then Arcane Shot three times, then Serpent Sting again. \"Not ready\" is Arcane Shot's 6 sec cooldown: Auto Shot keeps firing, press again.", "No pet (dead or not called): the first press marks and shoots at once. A new target starts over at Serpent Sting; a dead one is swapped for the nearest enemy."}},
    {name = "Aimed", title = "Aimed Shot", icon = "inv_spear_07", lo = 20, hi = 60,
     body = "#showtooltip Aimed Shot\n/petattack [harm,nodead]\n/cast [harm,nodead] !Auto Shot\n/cast [harm,nodead] Aimed Shot", pad = "RT+X", kb = "4",
     tips = {"Press it whenever its icon is ready: pet in, Auto Shot on, then Aimed Shot (a 2 sec cast that hits hard).", "It shares one 6 sec cooldown with Multi-Shot, so right after Pack it waits. Use Fight for Serpent Sting and Arcane Shot in between.", "Its own button: with Aimed Shot inside Fight, Arcane Shot sat waiting behind it."}},
    {name = "Sniper opener", title = "Sniper opener", icon = "hunter_pvp_snipershot", lo = 40, hi = 60,
     body = "#showtooltip Sniper Shot\n/petattack [harm,nodead]\n/cast [harm,nodead] Sniper Shot", pad = "RT+Right", kb = "3",
     tips = {"How to open: press Fight once (it marks the target and sends your pet without a shot), then this from up to 45 yards. The 4 sec cast lands as the pet arrives, and your next 3 shots reach 10 yards further.", "Its own button because of its 15 sec cooldown. On a long fight press it again when it is ready."}},
    {name = "Pack", title = "Pack: Multi-Shot", icon = "ability_upgrademoonglaive", lo = 18, hi = 60,
     body = "#showtooltip Multi-Shot\n/petattack [harm,nodead]\n/cast [harm,nodead] !Auto Shot\n/cast [harm,nodead] Multi-Shot\n/cast [combat] Rapid Fire", pad = "RT+B", kb = "2",
     tips = {"Two or three mobs close together: pet in, Auto Shot on, Multi-Shot hits 3 of them.", "From 26, Rapid Fire (+40% attack speed for 15 sec) fires with it in combat whenever it is ready. It is off the global cooldown, so nothing waits for it.", "Multi-Shot shares its 6 sec cooldown with Aimed Shot: while that runs the press does nothing."}},
    {name = "Too close", title = "Too close: Wing Clip", icon = "ability_rogue_trip", lo = 1, hi = 60,
     body = "#showtooltip\n/startattack [harm,nodead]\n/cast [harm,nodead] Wing Clip\n/cast [harm,nodead] Raptor Strike", pad = "LT+Y", kb = "Q",
     tips = {"A mob reached you: Wing Clip slows it for 10 sec and Raptor Strike lands on your next swing (it is off the global cooldown). Before 12 it is Raptor Strike only.", "Then walk out past 8 yards and press Fight: Auto Shot comes back on.", "Each press casts Wing Clip again, so press it once and move. Raptor Strike has a 6 sec cooldown: when it is not ready only Wing Clip goes out."}},
    {name = "Feign", title = "Feign Death", icon = "ability_rogue_feigndeath", lo = 30, hi = 60,
     body = "#showtooltip Feign Death\n/stopcasting\n/cast Feign Death", pad = "LT+X", kb = "F",
     tips = {"Drops you out of the fight at once, even in the middle of Aimed Shot, Sniper Shot or Volley: the mobs turn to your pet or walk home. 30 sec cooldown.", "Your pet keeps fighting. Press Pet back (LT+B) too if you want everything to reset."}},
    {name = "Pet care", title = "Pet care", icon = "ability_hunter_mendpet", lo = 10, hi = 60,
     body = "#showtooltip\n/cast [@pet,dead] Revive Pet; [nopet] Call Pet; Mend Pet", pad = "LT+A", kb = "E",
     tips = {"Pet dead: Revive Pet. Pet dismissed: Call Pet. Pet alive: Mend Pet (from 12).", "Mend Pet heals over 5 sec while you focus on it, so use it when the pet drops under half health and nothing is on you."}},
    {name = "Pet back", title = "Pet back", icon = "spell_nature_spiritwolf", lo = 10, hi = 60,
     body = "#showtooltip\n/petfollow", pad = "LT+B", kb = "R",
     tips = {"One press: your pet stops and runs back to you. Use it when the pet chases a runner into a new pack.", "After Feign Death it lets the mobs reset too. Press Fight to send the pet in again."}},
    {name = "Feed pet", title = "Feed pet", icon = "ability_hunter_beasttraining", lo = 10, hi = 60,
     body = "#showtooltip Feed Pet\n/cast Feed Pet\n/use Tough Jerky", pad = "LT+Down", kb = "Shift+4",
     tips = {"Edit first: replace \"Tough Jerky\" with a food your pet eats (its diet shows in the pet window).", "When: out of combat, every few fights. A happy pet deals more damage."}},
  }, plan = {{name = "Lethal Attacks", tree = "Marksmanship", from = 10, to = 14, why = "+5% crit on every attack — Forever widened it from shots to everything, Auto Shot and melee included. The best first five points for a ranged Hunter.", more = "+1% more crit.", max = 5, icon = "ability_searingarrow"}, {name = "Careful Aim", tree = "Marksmanship", from = 15, to = 19, why = "New in Forever: 100% of your Intellect becomes Attack Power at 5/5. Hunter mail is full of Intellect, so this is a big free damage boost — and it is the prerequisite for Mortal Shots.", more = "+20% more of your Intellect as AP.", max = 5, icon = "ability_hunter_zenarchery"}, {name = "Rapid Killing", tree = "Marksmanship", from = 20, to = 21, why = "Rapid Fire (+40% attack speed) comes back 2 min sooner, and after every non-trivial kill — or a mob dying with your Serpent Sting on it — your next Shot within 20 sec hits 20% harder. Perfect for chain-pulling.", more = "Faster Rapid Fire, bigger post-kill shot.", max = 2, icon = "ability_hunter_rapidkilling"}, {name = "Improved Stings", tree = "Marksmanship", from = 22, to = 24, why = "Serpent Sting is on every target, so +20% is free damage. It also shortens Viper Sting's new 15 sec cooldown.", more = "More Serpent Sting damage.", max = 3, icon = "ability_hunter_quickshot"}, {name = "Trueshot Aura", tree = "Marksmanship", from = 25, to = 25, why = "The earliest it opens (row 4 needs 15 points). Ranged Attack Power for you and your group — +20 now, growing to +100 by 60 as you train its ranks — and the prerequisite for Sniper Shot at 40.", more = "", max = 1, icon = "ability_trueshot"}, {name = "Mortal Shots", tree = "Marksmanship", from = 26, to = 30, why = "Needs Careful Aim 5/5. Ranged crits deal 30% more bonus damage. With Lethal Attacks you crit a lot — this makes each one count.", more = "+6% more crit damage.", max = 5, icon = "ability_piercedamage"}, {name = "Barrage", tree = "Marksmanship", from = 31, to = 33, why = "Aimed Shot, Multi-Shot and Volley hit 15% harder.", more = "+5% more.", max = 3, icon = "ability_upgrademoonglaive"}, {name = "Rapid Recuperation", tree = "Marksmanship", from = 34, to = 34, why = "Needs Rapid Killing. After Serpent Sting hits, 25% of your mana regen keeps going while you cast for 15 sec — fewer drink breaks.", more = "", max = 2, icon = "ability_hunter_rapidregeneration"}, {name = "Ranged Weapon Specialization", tree = "Marksmanship", from = 35, to = 39, why = "+5% ranged weapon damage: Auto Shot and every Shot.", more = "+1% more.", max = 5, icon = "inv_weapon_rifle_06"}, {name = "Sniper Shot", tree = "Marksmanship", from = 40, to = 40, why = "The capstone, open the moment you hit 40 (30 points, Trueshot Aura taken). A 4 sec cast from up to 45 yards on a 15 sec cooldown that hits hard (doubled in the 2 Nov update) and gives your next 3 shots +10 yards. Use it as your opener button.", more = "", max = 1, icon = "hunter_pvp_snipershot"}, {name = "Rapid Recuperation", tree = "Marksmanship", from = 41, to = 41, why = "Second point: 50% of mana regen while casting after a Serpent Sting, 100% once you spend Rapid Killing.", more = "", max = 2, icon = "ability_hunter_rapidregeneration"}, {name = "Hawk Eye", tree = "Marksmanship", from = 42, to = 44, why = "+6 yards range: pull from further away and get an extra shot in before anything reaches you.", more = "+2 more yards.", max = 3, icon = "ability_townwatch"}, {name = "Efficiency", tree = "Marksmanship", from = 45, to = 49, why = "Shots, Stings and (new in Forever) melee abilities 15% cheaper — mana is what stops long questing sessions.", more = "3% cheaper again.", max = 5, icon = "spell_frost_wizardmark"}, {name = "Deadly Aspects", tree = "Beast Mastery", from = 50, to = 54, why = "Every Marksmanship talent worth having is done. Deadly Aspects (Beast Mastery row 1) gives Auto Shot a 10% chance at 5/5 for +30% attack speed for 12 sec with Aspect of the Hawk.", more = "+2% more proc chance.", max = 5, icon = "spell_nature_ravenform"}, {name = "Focused Fire", tree = "Beast Mastery", from = 55, to = 56, why = "New in Forever: you and your pet deal 2% more while it is out — and you always have it out.", more = "+1% more.", max = 2, icon = "inv_weapon_crossbow_10"}, {name = "Improved Tracking", tree = "Survival", from = 57, to = 60, why = "New in Forever (merges Monster and Humanoid Slaying): track the creature type you are fighting (not herbs/ore) for +4% damage against it with these four points.", more = "+1% more.", max = 5, icon = "inv_misc_head_dragon_black"}}, train = {{level = 1, spells = {"Auto Shot", "Raptor Strike (Rank 1)", "Track Beasts"}, notes = {"Your main damage. Fires only past 8 yards and after half a second standing still; keeps firing while you cast Aimed Shot. The Fight macro keeps it running.", "Melee hit for when a mob reaches you.", "Find and track — with Improved Tracking (57+) also +damage."}, icons = {"ability_whirlwind", "ability_meleedamage", "ability_tracking"}}, {level = 4, spells = {"Serpent Sting (Rank 1)", "Aspect of the Monkey"}, notes = {"DoT on every target.", "+8% dodge when something is on you."}, icons = {"ability_hunter_quickshot", "ability_hunter_aspectofthemonkey"}}, {level = 6, spells = {"Hunter's Mark (Rank 1)", "Arcane Shot (Rank 1)"}, notes = {"More Ranged Attack Power against the target.", "Instant shot, 6 sec cooldown."}, icons = {"ability_hunter_snipershot", "ability_impalingbolt"}}, {level = 8, spells = {"Raptor Strike (Rank 2)", "Concussive Shot"}, notes = {"Melee hit for when a mob reaches you.", "Slow runners and approaching mobs."}, icons = {"ability_meleedamage", "spell_frost_stun"}}, {level = 10, spells = {"Aspect of the Hawk (Rank 1)", "Tame Beast", "Beast Training", "Serpent Sting (Rank 2)", "Track Humanoids"}, notes = {"Your normal aspect — always on in fights.", "Class quest at 10 — your pet kit: Tame Beast, Call, Dismiss, Revive and Feed Pet.", "Train your pet: keep Growl at its best rank so it holds aggro.", "DoT on every target.", "Tracking."}, icons = {"spell_nature_ravenform", "ability_hunter_beasttaming", "ability_hunter_beastcall02", "ability_hunter_quickshot", "spell_holy_prayerofhealing"}}, {level = 12, spells = {"Mend Pet (Rank 1)", "Arcane Shot (Rank 2)", "Wing Clip (Rank 1)", "Distracting Shot (Rank 1)"}, notes = {"Heal your pet over time.", "Instant shot, 6 sec cooldown.", "Slow in melee, then step out.", "Group utility."}, icons = {"ability_hunter_mendpet", "ability_impalingbolt", "ability_rogue_trip", "spell_arcane_blink"}}, {level = 14, spells = {"Scare Beast (Rank 1)", "Eagle Eye", "Eyes of the Beast"}, notes = {"Fear an extra beast.", "Scouting.", "Scouting."}, icons = {"ability_druid_cower", "ability_hunter_eagleeye", "ability_eyeoftheowl"}}, {level = 16, spells = {"Raptor Strike (Rank 3)", "Immolation Trap (Rank 1)", "Mongoose Bite (Rank 1)"}, notes = {"Melee hit for when a mob reaches you.", "Fire DoT trap. All traps share a 30 sec cooldown.", "Melee hit after you dodge."}, icons = {"ability_meleedamage", "spell_fire_flameshock", "ability_hunter_swiftstrike"}}, {level = 18, spells = {"Multi-Shot", "Aspect of the Hawk (Rank 2)", "Serpent Sting (Rank 3)", "Track Undead"}, notes = {"Hits 3 targets. Shares a cooldown with Aimed Shot.", "Your normal aspect — always on in fights.", "DoT on every target.", "Tracking."}, icons = {"ability_upgrademoonglaive", "spell_nature_ravenform", "ability_hunter_quickshot", "spell_shadow_darksummoning"}}, {level = 20, spells = {"Aimed Shot (Rank 1)", "Freezing Trap (Rank 1)", "Aspect of the Cheetah", "Mend Pet (Rank 2)", "Arcane Shot (Rank 3)", "Disengage (Rank 1)", "Distracting Shot (Rank 2)"}, notes = {"Trainable in Forever: 2 sec cast, big hit.", "Freeze an add. Traps work in combat in Forever.", "Travel speed — turn it off before fighting.", "Heal your pet over time.", "Instant shot, 6 sec cooldown.", "Drops threat — groups.", "Group utility."}, icons = {"inv_spear_07", "spell_frost_chainsofice", "ability_mount_jungletiger", "ability_h