ity_mount_pinktiger", "ability_gouge", "spell_arcane_blink"}}, {level = 52, spells = {"Aimed Shot (Rank 5)", "Mend Pet (Rank 6)", "Arcane Shot (Rank 7)"}, notes = {"Trainable in Forever: 2 sec cast, big hit.", "Heal your pet over time.", "Instant shot, 6 sec cooldown."}, icons = {"inv_spear_07", "ability_hunter_mendpet", "ability_impalingbolt"}}, {level = 54, spells = {"Explosive Trap (Rank 3)"}, notes = {"AoE fire trap."}, icons = {"spell_fire_selfdestruct"}}, {level = 56, spells = {"Raptor Strike (Rank 8)", "Immolation Trap (Rank 5)", "Viper Sting (Rank 3)", "Aspect of the Wild (Rank 2)"}, notes = {"Melee hit for when a mob reaches you.", "Fire DoT trap. All traps share a 30 sec cooldown.", "Drains mana; 15 sec cooldown in Forever. PvP.", "Nature resistance."}, icons = {"ability_meleedamage", "spell_fire_flameshock", "ability_hunter_aimedshot", "spell_nature_protectionformnature"}}, {level = 58, spells = {"Sniper Shot (Rank 3)", "Aspect of the Hawk (Rank 6)", "Hunter's Mark (Rank 4)", "Serpent Sting (Rank 8)", "Volley (Rank 3)", "Mongoose Bite (Rank 4)"}, notes = {"Your long-range opener.", "Your normal aspect — always on in fights.", "More Ranged Attack Power against the target.", "DoT on every target.", "Channeled AoE for packs.", "Melee hit after you dodge."}, icons = {"hunter_pvp_snipershot", "spell_nature_ravenform", "ability_hunter_snipershot", "ability_hunter_quickshot", "ability_marksmanship", "ability_hunter_swiftstrike"}}, {level = 60, spells = {"Aimed Shot (Rank 6)", "Mend Pet (Rank 7)", "Aspect of the Hawk (Rank 7)", "Serpent Sting (Rank 9)", "Arcane Shot (Rank 8)", "Trueshot Aura (Rank 5)", "Wing Clip (Rank 3)", "Freezing Trap (Rank 3)", "Tranquilizing Shot", "Aspect of the Beast (Rank 4)", "Lacerate (Rank 4)", "Distracting Shot (Rank 6)"}, notes = {"Trainable in Forever: 2 sec cast, big hit.", "Heal your pet over time.", "Your normal aspect — always on in fights.", "DoT on every target.", "Instant shot, 6 sec cooldown.", "New rank of your aura.", "Slow in melee, then step out.", "Freeze an add. Traps work in combat in Forever.", "Removes enrage — raids.", "Melee aspect.", "Survival melee bleed.", "Group utility."}, icons = {"inv_spear_07", "ability_hunter_mendpet", "spell_nature_ravenform", "ability_hunter_quickshot", "ability_impalingbolt", "ability_trueshot", "ability_rogue_trip", "spell_frost_chainsofice", "spell_nature_drowsy", "ability_mount_pinktiger", "ability_gouge", "spell_arcane_blink"}}}, br = {{level = 1, icon = "ability_whirlwind", title = "Before Your Pet", range = "Levels 1–9", intro = "No pet until 10, so pull one mob at a time: shoot from range and finish in melee.", steps = {"Auto Shot from max range.", "Fight (RT+A) pulls with Serpent Sting (4); from 6 it marks and shoots, then Serpent Sting and Arcane Shot.", "When it reaches you: Too close (LT+Y) for Raptor Strike, and melee it down.", "Concussive Shot (8) on anything that runs."}, stepIcons = {"ability_whirlwind", "ability_hunter_quickshot", "ability_meleedamage", "spell_frost_stun"}}, {level = 10, icon = "ability_hunter_beasttaming", title = "Your Pet", range = "Levels 10–19", intro = "Do your level-10 class quest to tame a beast, then feed it at once. From now on it tanks and you shoot.", steps = {"Any beast your level works; a cat or boar hits hardest, a bear or turtle tanks best.", "Aspect of the Hawk on at all times.", "Press Fight: it marks the target and sends your pet without a shot. Press it again once the pet is fighting.", "Then Fight goes Serpent Sting and three Arcane Shots, with Auto Shot running between.", "Mend Pet (12) when it drops under half health.", "Mob on you? Too close (LT+Y): Wing Clip (12) and Raptor Strike, then step back past 8 yards and press Fight.", "Multi-Shot (18) when 2–3 mobs are grouped."}, stepIcons = {"ability_hunter_beasttaming", "spell_nature_ravenform", "ability_hunter_beastcall", "ability_impalingbolt", "ability_hunter_mendpet", "ability_rogue_trip", "ability_upgrademoonglaive"}}, {level = 20, icon = "inv_spear_07", title = "Aimed Shot", range = "Levels 20–29", intro = "Aimed Shot is trainable at 20 in Forever: a 2-second cast on a 6-second cooldown shared with Multi-Shot. With the pet holding aggro you have time to cast it.", steps = {"Fight for Mark, Serpent and Arcane; press Aimed (RT+X) whenever it is ready.", "Freezing Trap (20) works in combat in Forever — drop it at your feet for an add. All traps share a 30 sec cooldown.", "Aspect of the Cheetah (20) for travel; switch back to Hawk before fights.", "Trueshot Aura (25) on always; from 40 it lasts 30 min, so recast it.", "Rapid Fire (26): Pack fires it in combat; on a tough single mob press it yourself. Rapid Killing (20–21) brings it back faster."}, stepIcons = {"inv_spear_07", "spell_frost_chainsofice", "ability_mount_jungletiger", "ability_trueshot", "ability_hunter_runningshot"}}, {level = 30, icon = "ability_rogue_feigndeath", title = "Feign Death", range = "Levels 30–39", intro = "Feign Death (30) drops all threat — your reset on bad pulls. Mortal Shots and Barrage make crits and Aimed Shots much stronger.", steps = {"Too much on you: Feign (LT+X), even mid-cast; let the pet tank or die, stand up and shoot.", "Explosive Trap (34) at your feet, then pull the pack onto it.", "Pet died? Revive Pet out of combat — the Pet care button does it.", "Feed Pet after every few fights to keep it happy — unhappy pets deal less damage."}, stepIcons = {"ability_rogue_feigndeath", "spell_fire_selfdestruct", "ability_hunter_beastsoothe", "ability_hunter_beasttraining"}}, {level = 40, icon = "hunter_pvp_snipershot", title = "Sniper Shot", range = "Levels 40–60", intro = "Sniper Shot (40) is a 4-second, 45-yard opener that hits hard and adds 10 yards to your next 3 shots. Open every pull with it.", steps = {"Fight once (Mark, pet in) → Sniper opener from max range → then Fight (Serpent, Arcane) and Aimed when it is ready.", "Volley (40) on a pack your pet is holding.", "Rapid Fire on elites and rough pulls.", "Aspect of the Pack (40) for group travel — anyone hit is dazed."}, stepIcons = {"hunter_pvp_snipershot", "ability_marksmanship", "ability_hunter_runningshot", "ability_mount_whitetiger"}}}, spec = "Marksmanship", guide = "Marksmanship Hunter"},
  DRUID = {macros = {
    {name = "Fight", title = "Fight", icon = "spell_nature_abolishmagic", lo = 1, hi = 3,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/startattack\n/cast Wrath", pad = "RT+A", kb = "1",
     tips = {"Every press: Wrath on your target. With no live enemy targeted it first picks the nearest one, so one press after a kill finds the next.", "Auto-attack is switched on too: once the enemy reaches you, your staff hits between casts."}},
    {name = "Fight", title = "Fight", icon = "spell_nature_abolishmagic", lo = 4, hi = 9,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/startattack\n/castsequence reset=target/combat Wrath, Moonfire, Wrath", pad = "RT+A", kb = "1",
     tips = {"Each press: Wrath, Moonfire, Wrath, then it starts over at Wrath. A new target or the end of the fight also starts it over.", "Auto-attack is on: once the enemy is on you, you can stop pressing and melee it down to save mana.", "With no live enemy targeted, the first press picks the nearest one."}},
    {name = "Fight", title = "Pull / Bear", icon = "spell_nature_starfall", lo = 10, hi = 19,
     body = "#showtooltip\n/dismount\n/cancelform [noform:1,known:5487]\n/cast [nocombat,harm,nodead] Moonfire; [noform:1] Bear Form\n/cast Wrath", pad = "RT+A", kb = "1",
     tips = {"Out of combat with an enemy targeted: Moonfire pulls it from range. Otherwise (no target, or in combat) it shifts you into Bear Form.", "After Heal up drops your form mid-fight, press it once to get back into Bear. The bear bar's RT+A then fights.", "Before you have done the Bear Form quest it casts Wrath instead, so it keeps fighting.", "From 18 Fight Bear pulls with Faerie Fire straight from Bear Form. From 20 this button shifts you into Cat Form instead."}},
    {name = "Fight", title = "Cat Form", icon = "ability_druid_catform", lo = 20, hi = 60,
     body = "#showtooltip\n/dismount\n/cancelform [noform:3,known:1066,known:768][noform:2,noknown:1066,known:768]\n/cast [noform:3,known:1066][noform:2,noknown:1066] Cat Form\n/cast [noform:1,noknown:768] Dire Bear Form\n/cast [noform:1,noknown:768] Bear Form", pad = "RT+A", kb = "1",
     tips = {"One press: Cat Form, off your mount first if you are on one. It never toggles you out of Cat, and from Travel Form (30) it takes you straight in. Before the Cat Form quest it shifts you into Bear.", "After Heal up or Buffs drop your form, press it to get back into Cat. The cat bar's RT+A then fights: Faerie Fire pulls from range, Prowl Cat opens from stealth.", "Bear Form, for packs or a fight gone wrong, is on your stance bar."}},
    {name = "Heal up", title = "Heal up", icon = "spell_nature_healingtouch", lo = 1, hi = 11,
     body = "#showtooltip\n/cancelform\n/cast [@player] Healing Touch", pad = "LT+A", kb = "Q",
     tips = {"One press: drops any form and casts Healing Touch on yourself, even with an enemy targeted.", "Put it on your Cat and Bear bars too (LT+A) if your bar changes when you shift, so it works from every form.", "From 12, this starts with Rejuvenation in combat and follows with Regrowth."}},
    {name = "Heal up", title = "Heal up", icon = "spell_nature_healingtouch", lo = 12, hi = 60,
     body = "#showtooltip\n/cancelform\n/castsequence [@player,combat] reset=combat Rejuvenation, Regrowth\n/castsequence [@player,nocombat] reset=combat Healing Touch, Regrowth", pad = "LT+A", kb = "Q",
     tips = {"Drops your form and heals you. In combat, start with instant Rejuvenation and press again for Regrowth. Between fights, start with Healing Touch and press again for Regrowth if needed. The sequences reset when combat ends.", "It drops your form before attempting either heal, even when you are low on mana or a cast-time heal is blocked by movement.", "From 47 Furor gives back part of the Energy you had when you return to Cat Form, all of it at 51, plus 10 per second you spent out of it.", "Put it on your Cat and Bear bars too (LT+A) if your bar changes when you shift."}},
    {name = "Buffs", title = "Thorns / Mark", icon = "spell_nature_thorns", lo = 6, hi = 60,
     body = "#showtooltip\n/cancelform\n/castsequence [@mouseover,help,nodead][help,nodead][@player] reset=60 Thorns, Mark of the Wild", pad = "LT+Up", kb = "G",
     tips = {"First press: Thorns. Press again within a minute: Mark of the Wild. After a minute without a press it starts at Thorns again.", "It buffs the friend you hover with the mouse, else your friendly target, else you. Clear a quest giver from your target first or it buffs them.", "Drops Cat or Bear Form first: shift back afterwards."}},
    {name = "Fight Bear", title = "Fight - Bear", icon = "ability_druid_maul", lo = 10, hi = 60,
     body = "#showtooltip Maul\n/dismount\n/cancelform [noform:1]\n/cast [noform:1] Dire Bear Form\n/cast [noform:1] Bear Form\n/targetenemy [noharm][dead]\n/startattack\n/cast [nocombat] Faerie Fire\n/cast [nocombat] Enrage\n/cast Maul\n/cast [combat] Enrage", pad = "RT+A (in Bear Form)", kb = "1 (in Bear Form)",
     tips = {"From another form or a mount, press to shift into Bear, then press again to fight.", "In combat each press queues Maul on your next swing, then Enrage when it is ready. Enrage comes last, so its cooldown never holds up Maul.", "Out of combat it pulls: Faerie Fire (18) on your target, then Enrage (12) for Rage while it runs in. Press it when you mean to fight, not to look around.", "No Maul yet means not enough Rage (15, 10 with Ferocity 5/5 at 14): keep pressing. Shifted in mid-fight with no Rage? Cast Enrage from your bear bar first.", "Where: your Bear Form bar, RT+A. With no live enemy targeted it picks the nearest one."}},
    {name = "Pack Bear", title = "Pack - Bear", icon = "inv_misc_monsterclaw_03", lo = 16, hi = 60,
     body = "#showtooltip Swipe\n/targetenemy [noharm][dead]\n/startattack\n/castsequence reset=combat Demoralizing Roar, Swipe, Swipe, Swipe, Swipe, Swipe\n/cast Maul", pad = "RT+B (in Bear Form)", kb = "2 (in Bear Form)",
     tips = {"For 2 or more enemies. First press of a fight: Demoralizing Roar. Then Swipe on every press (up to 3 enemies), and Roar again after 5 Swipes.", "Maul rides along on your next swing when Rage is left after the Swipe.", "When your target dies it picks the next one and carries on; the sequence starts over only when the fight ends.", "On one hard-hitting enemy, press it once for the Roar, then use Fight Bear."}},
    {name = "Panic Bear", title = "Panic - Bear", icon = "ability_bullrush", lo = 36, hi = 60,
     body = "#showtooltip Frenzied Regeneration\n/dismount\n/cancelform [noform:1]\n/cast [noform:1] Dire Bear Form\n/cast [noform:1] Bear Form\n/cast Frenzied Regeneration\n/cast Enrage", pad = "LT+X (in Bear Form)", kb = "F (in Bear Form)",
     tips = {"Dismounts and shifts into Bear or Dire Bear if needed. In Bear, press for Frenzied Regeneration to turn Rage into health for 10 sec and Enrage to feed it.", "Frenzied Regeneration has a 3 min cooldown. While it cools down, try Barkskin (44) or Heal up.", "Where: Bear Form bar, LT+X. Also place it on your caster and Cat bars for emergencies."}},
    {name = "Fight Cat", title = "Fight - Cat", icon = "ability_druid_rake", lo = 20, hi = 23,
     body = "#showtooltip\n/dismount\n/cancelform [noform:3,known:1066][noform:2,noknown:1066]\n/cast [noform] Cat Form\n/targetenemy [noharm][dead]\n/startattack [nostealth]\n/cast [nocombat,nostealth] Faerie Fire\n/castsequence reset=target/combat Claw, Claw, Claw, Rip", pad = "RT+A (in Cat Form)", kb = "1 (in Cat Form)",
     tips = {"From another form or a mount, press to shift into Cat, then press again to fight.", "Out of combat and not prowling: Faerie Fire pulls your target from 30 yards. Then each press: Claw, Claw, Claw, Rip, and again.", "Not enough Energy just means wait: keep pressing and it carries on from the step it reached. A new target or the end of the fight starts it over.", "While you prowl it leaves auto-attack off, so walking in won't break Prowl. Out of mana it can't pull: walk in, your first hit starts the fight.", "Where: Cat Form bar, RT+A. With no live enemy targeted it picks the nearest one."}},
    {name = "Fight Cat", title = "Fight - Cat", icon = "ability_druid_ferociousbite", lo = 24, hi = 60,
     body = "#show\n/dismount\n/cancelform [noform:3,known:1066][noform:2,noknown:1066]\n/use [noform]Cat Form\n/targetenemy [noharm][dead]\n/startattack [nostealth]\n/cast [nocombat,nostealth]Faerie Fire\n/castsequence reset=target/combat Rake,Claw,Claw,Claw,Ferocious Bite", pad = "RT+A (in Cat Form)", kb = "1 (in Cat Form)",
     tips = {"From another form or a mount, press to shift into Cat, then press again to fight.", "Out of combat and not prowling: Faerie Fire pulls from 30 yards. In the fight each press: Rake, Claw, Claw, Claw, Ferocious Bite, then again from Rake.", "From Prowl it opens with Rake from any side, and it leaves auto-attack off while you prowl, so walking in won't break Prowl. A new target or the end of the fight starts it over.", "Not enough Energy means wait: it carries on from the step it reached. From 46 Shifting Power on Prowl Cat refills it. From 40 Rend and Tear (15% at 44) makes your hits on a bleeding target stronger, so Rake comes first.", "Where: Cat Form bar, RT+A. With no live enemy targeted it picks the nearest one."}},
    {name = "Prowl Cat", title = "Prowl / Shred", icon = "ability_ambush", lo = 20, hi = 31,
     body = "#showtooltip\n/dismount\n/cancelform [noform:3,known:1066,known:768][noform:2,noknown:1066,known:768]\n/cast [noform:3,known:1066][noform:2,noknown:1066] Cat Form\n/cast [nocombat,nostealth] Prowl; Shred", pad = "RT+B (in Cat Form)", kb = "2 (in Cat Form)",
     tips = {"From another form or a mount, shift into Cat first. Press again to Prowl or use your combat ability.", "Out of combat: Prowl. While prowling, get behind the enemy and press it again: Shred opens the fight.", "In combat it casts Shred, for when you stand behind the enemy (in groups, or when it is busy with someone else).", "If your bar changes while you prowl, put this and Fight Cat on the Prowl bar too. Where: Cat Form bar, RT+B."}},
    {name = "Prowl Cat", title = "Prowl / Ravage", icon = "ability_druid_ravage", lo = 32, hi = 45,
     body = "#showtooltip\n/dismount\n/cancelform [noform:3,known:1066,known:768][noform:2,noknown:1066,known:768]\n/cast [noform:3,known:1066][noform:2,noknown:1066] Cat Form\n/cast [nocombat,nostealth] Prowl; [stealth] Ravage; Shred", pad = "RT+B (in Cat Form)", kb = "2 (in Cat Form)",
     tips = {"From another form or a mount, shift into Cat first. Press again to Prowl or use your combat ability.", "Out of combat: Prowl. While prowling, from behind: Ravage, your biggest opener. At full Energy, Poised (32) makes it 10 Energy cheaper.", "In combat it casts Shred, for when you stand behind the enemy.", "From the front, Fight Cat opens with Rake instead. Pounce (36, also from behind) stuns: cast it from the spellbook when you want the stun.", "From 46 the in-combat press becomes Shifting Power. If your bar changes while you prowl, put this on the Prowl bar too."}},
    {name = "Prowl Cat", title = "Prowl / Energy", icon = "spell_druid_displacement", lo = 46, hi = 60,
     body = "#showtooltip\n/dismount\n/cancelform [noform:3,known:1066,known:768][noform:2,noknown:1066,known:768]\n/cast [noform:3,known:1066][noform:2,noknown:1066] Cat Form\n/cast [combat] Shifting Power; [nostealth] Prowl; Ravage", pad = "RT+B (in Cat Form)", kb = "2 (in Cat Form)",
     tips = {"From another form or a mount, shift into Cat first. Press again to Prowl or use your combat ability.", "Out of combat: Prowl. While prowling, from behind: Ravage.", "In combat: Shifting Power (46), 40 Energy for mana. Press it below 60 Energy. It has an 8 sec cooldown, so nothing happens while it cools.", "Each use costs a share of your base mana: keep enough for a Heal up. Shred in combat now comes from the spellbook.", "If your bar changes while you prowl, put this on the Prowl bar too."}},
    {name = "Cancel Form", title = "Cancel Form", icon = "spell_nature_wispsplode", lo = 10, hi = 60,
     body = "#showtooltip [form:1,known:9634]Dire Bear Form;[form:1]Bear Form;[form:2,known:1066]Aquatic Form;[form:3,known:1066][form:2,noknown:1066]Cat Form;[form:4,known:1066][form:3,noknown:1066]Travel Form;[form:5][form:4,noknown:1066]Moonkin Form\n/cancelform", pad = "", kb = "",
     tips = {"Returns you to caster form. The tooltip follows your current form once you have learned Bear and Cat Form, with or without Aquatic Form."}},
  }, plan = {{name = "Ferocity", tree = "Feral Combat", from = 10, to = 14, why = "At 5/5 Maul (and Swipe at 16) cost 5 less Rage; Claw (20) and Rake (24) cost 5 less Energy.", more = "1 less Rage or Energy more.", max = 5, icon = "ability_hunter_pet_hyena"}, {name = "Heart of the Wild", tree = "Restoration", from = 15, to = 19, why = "Restoration row 1 (Forever moved it out of Feral): +20% Stamina in Bear, +10% Strength in Cat, +10% Intellect.", more = "Bigger form bonuses.", max = 5, icon = "spell_holy_blessingofagility"}, {name = "Feral Swiftness", tree = "Feral Combat", from = 20, to = 21, why = "Your Cat Form (20) runs 30% faster — less walking between mobs — and +4% dodge.", more = "", max = 2, icon = "spell_nature_spiritwolf"}, {name = "Thick Hide", tree = "Feral Combat", from = 22, to = 24, why = "+3 base Armor per level in forms (about +70 at 24): fewer heals between pulls. Opens row 3.", more = "+1 Armor per level more.", max = 3, icon = "inv_misc_pelt_bear_03"}, {name = "Sharpened Claws", tree = "Feral Combat", from = 25, to = 26, why = "+6% crit in Cat and Bear — and Blood Frenzy (33) turns those crits into extra combo points.", more = "", max = 2, icon = "inv_misc_monsterclaw_04"}, {name = "Savage Fury", tree = "Feral Combat", from = 27, to = 28, why = "Claw, Rake, Shred, Maul and Swipe deal 10% more.", more = "", max = 2, icon = "ability_druid_ravage"}, {name = "Shredding Attacks", tree = "Feral Combat", from = 29, to = 29, why = "Shred costs 6 less Energy. Your 15th Feral point — opens row 4 for Predatory Strikes at 30.", more = "", max = 3, icon = "spell_shadow_vampiricaura"}, {name = "Predatory Strikes", tree = "Feral Combat", from = 30, to = 32, why = "Earliest it opens. Attack Power in forms +150% of your level (+48 at 32, +90 at 60). Unlocks Rend and Tear.", more = "+50% of level more.", max = 3, icon = "ability_hunter_pet_cat"}, {name = "Blood Frenzy", tree = "Feral Combat", from = 33, to = 34, why = "Needs Sharpened Claws 2/2. At 2/2 every Claw or Rake crit adds an extra combo point; Bear crits give 5 Rage.", more = "Now on every crit.", max = 2, icon = "ability_ghoulfrenzy"}, {name = "Leader of the Pack", tree = "Feral Combat", from = 35, to = 35, why = "Earliest it opens (20 Feral points). +3% crit for you and your group while in forms.", more = "", max = 1, icon = "spell_nature_unyeildingstamina"}, {name = "Natural Instinct", tree = "Feral Combat", from = 36, to = 37, why = "Your ability crits get a 20% bigger bonus, and heals gain 25% of your Intellect as healing power.", more = "", max = 2, icon = "ability_druid_predatoryinstincts"}, {name = "Shredding Attacks", tree = "Feral Combat", from = 38, to = 39, why = "Shredding Attacks 3/3 (Shred 18 less Energy) — your 25th Feral point, so row 6 opens at 40.", more = "", max = 3, icon = "spell_shadow_vampiricaura"}, {name = "Rend and Tear", tree = "Feral Combat", from = 40, to = 44, why = "Earliest it opens. +3% ability damage per point (15% at 5/5) on bleeding targets — open with Rake.", more = "+3% more.", max = 5, icon = "ability_druid_primalagression"}, {name = "Predatory Discipline", tree = "Feral Combat", from = 45, to = 45, why = "Ferocious Bite stops eating your spare Energy but still hits harder from it. Unlocks Shifting Power.", more = "", max = 1, icon = "spell_druid_savagery"}, {name = "Shifting Power", tree = "Feral Combat", from = 46, to = 46, why = "Row 7 (30 Feral points). Spend 55% of base mana for 40 Energy, 8 sec cooldown: your Energy refill, on Prowl Cat in combat.", more = "", max = 1, icon = "spell_druid_displacement"}, {name = "Furor", tree = "Feral Combat", from = 47, to = 51, why = "At 5/5, shifting back to Cat after a heal keeps your old Energy plus 10 per sec spent out of form (up to 100).", more = "+20% Energy kept, +2 per sec.", max = 5, icon = "spell_holy_blessingofstamina"}, {name = "Genesis", tree = "Balance", from = 52, to = 56, why = "Balance row 1: Rake, Rip and Rejuvenation tick 10% harder at 5/5.", more = "+2% more.", max = 5, icon = "spell_arcane_arcane03"}, {name = "Nature's Majesty", tree = "Balance", from = 57, to = 58, why = "Balance row 2 (opened by Genesis): +4% crit with spells and melee.", more = "", max = 2, icon = "inv_staff_01"}, {name = "Feral Instinct", tree = "Feral Combat", from = 59, to = 60, why = "Swipe deals 20% more for Bear packs; Prowl is harder to spot.", more = "", max = 3, icon = "ability_ambush"}}, train = {{level = 1, spells = {"Wrath", "Healing Touch", "Mark of the Wild"}, notes = {"Pull from range.", "Big heal between pulls.", "Keep it up."}, icons = {"spell_nature_abolishmagic", "spell_nature_healingtouch", "spell_nature_regeneration"}}, {level = 4, spells = {"Moonfire", "Rejuvenation"}, notes = {"Instant pull.", "Heal over time."}, icons = {"spell_nature_starfall", "spell_nature_rejuvenation"}}, {level = 6, spells = {"Thorns", "Train new ranks of your attacks and heals every visit."}, notes = {"Free damage when hit.", "Train new ranks of your attacks and heals every visit."}, icons = {"spell_nature_thorns", "inv_misc_book_09"}}, {level = 8, spells = {"Entangling Roots", "Train new ranks of your attacks and heals every visit."}, notes = {"Root a runner or an extra mob.", "Train new ranks of your attacks and heals every visit."}, icons = {"spell_nature_stranglevines", "inv_misc_book_09"}}, {level = 10, spells = {"Bear Form", "Maul", "Demoralizing Roar", "Growl", "Nature's Grasp", "Teleport: Moonglade"}, notes = {"From a quest at 10, not the trainer.", "Bear: next-swing hit.", "Bear: less damage taken. Pack Bear (16) opens every fight with it.", "Groups.", "Roots the next melee attacker. Castable in forms; lasts 45 sec.", "Travel."}, icons = {"ability_racial_bearform", "ability_druid_maul", "ability_druid_demoralizingroar", "ability_physical_taunt", "spell_nature_natureswrath", "spell_arcane_teleportmoonglade"}}, {level = 12, spells = {"Regrowth", "Enrage", "Revive", "Train new ranks of your attacks and heals every visit."}, notes = {"Heal plus heal over time.", "Rage to open in Bear: Fight Bear casts it on the pull, and in combat when it is ready.", "Resurrect, out of combat only.", "Train new ranks of your attacks and heals every visit."}, icons = {"spell_nature_resistnature", "ability_druid_enrage", "ability_druid_lunarguidance", "inv_misc_book_09"}}, {level = 14, spells = {"Bash", "Cure Poison", "Train new ranks of your attacks and heals every visit."}, notes = {"Bear stun / interrupt.", "Utility.", "Train new ranks of your attacks and heals every visit."}, icons = {"ability_druid_bash", "spell_nature_nullifypoison", "inv_misc_book_09"}}, {level = 16, spells = {"Swipe", "Aquatic Form", "Train new ranks of your attacks and heals every visit."}, notes = {"Bear: hits up to 3 nearby enemies.", "From a quest at 16.", "Train new ranks of your attacks and heals every visit."}, icons = {"inv_misc_monsterclaw_03", "ability_druid_aquaticform", "inv_misc_book_09"}}, {level = 18, spells = {"Faerie Fire", "Hibernate", "Train new ranks of your attacks and heals every visit."}, notes = {"Armor down for 40 sec. Works in Cat and Bear Form too: Fight Cat and Fight Bear pull with it.", "Beast/dragonkin CC.", "Train new ranks of your attacks and heals every visit."}, icons = {"spell_nature_faeriefire", "spell_nature_sleep", "inv_misc_book_09"}}, {level = 20, spells = {"Cat Form", "Claw", "Omen of Clarity", "Prowl", "Rip", "Shred", "Rebirth", "Starfire", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Your leveling form from here.", "Combo point builder.", "Passive in Forever, trained at 20: attacks and spells can make your next ability free. Nothing to rebuff.", "Stealth. Prowl Cat: press to prowl, press again from behind to open.", "Bleed finisher.", "Big builder from behind.", "Combat resurrect.", "Balance nuke.", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"ability_druid_catform", "ability_druid_rake", "spell_nature_crystalball", "ability_ambush", "ability_ghoulfrenzy", "spell_shadow_vampiricaura", "spell_nature_reincarnation", "spell_arcane_starfire", "inv_misc_book_09"}}, {level = 22, spells = {"Soothe Animal", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Utility.", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"ability_hunter_beastsoothe", "inv_misc_book_09"}}, {level = 24, spells = {"Ferocious Bite", "Rake", "Remove Curse", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Damage finisher.", "Builder plus bleed.", "Utility.", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"ability_druid_ferociousbite", "ability_druid_disembowel", "spell_holy_removecurse", "inv_misc_book_09"}}, {level = 26, spells = {"Dash", "Abolish Poison", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Cat sprint.", "Utility.", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"ability_druid_dash", "spell_nature_nullifypoison_02", "inv_misc_book_09"}}, {level = 28, spells = {"Challenging Roar", "Cower", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Groups.", "Groups.", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"ability_druid_challangingroar", "ability_druid_cower", "inv_misc_book_09"}}, {level = 30, spells = {"Travel Form", "Tranquility", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Fast outdoor travel.", "Groups.", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"ability_druid_travelform", "spell_nature_tranquility", "inv_misc_book_09"}}, {level = 32, spells = {"Ravage", "Poised", "Track Humanoids", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Opener from Prowl, behind.", "Passive: out of combat at full Energy, your next Energy ability costs 10 less.", "Cat tracking.", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"ability_druid_ravage", "ability_racial_darkflight", "ability_tracking", "inv_misc_book_09"}}, {level = 34, spells = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"inv_misc_book_09"}}, {level = 36, spells = {"Pounce", "Frenzied Regeneration", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Stun opener from Prowl; like Ravage it needs you behind the target.", "Bear self-heal. Panic Bear casts it with Enrage.", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"ability_druid_supriseattack", "ability_bullrush", "inv_misc_book_09"}}, {level = 38, spells = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"inv_misc_book_09"}}, {level = 40, spells = {"Dire Bear Form", "Feline Grace", "Innervate", "Hurricane", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Replaces Bear Form.", "Passive.", "Mana back.", "Balance AoE.", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"ability_racial_bearform", "inv_feather_01", "spell_nature_lightning", "spell_nature_cyclone", "inv_misc_book_09"}}, {level = 42, spells = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"inv_misc_book_09"}}, {level = 44, spells = {"Barkskin", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Damage reduction, usable in forms.", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"spell_nature_stoneclawtotem", "inv_misc_book_09"}}, {level = 46, spells = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"inv_misc_book_09"}}, {level = 48, spells = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"inv_misc_book_09"}}, {level = 50, spells = {"Gift of the Wild", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Group buff.", "Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"spell_nature_regeneration", "inv_misc_book_09"}}, {level = 52, spells = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"inv_misc_book_09"}}, {level = 54, spells = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"inv_misc_book_09"}}, {level = 56, spells = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"inv_misc_book_09"}}, {level = 58, spells = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"inv_misc_book_09"}}, {level = 60, spells = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, notes = {"Train new ranks of Claw, Rake, Rip, Ferocious Bite, Maul and your heals every visit."}, icons = {"inv_misc_book_09"}}}, br = {{level = 1, icon = "spell_nature_regeneration", title = "Before Forms", range = "Levels 1–9", intro = "A caster with a staff until 10. Pull with spells, finish in melee, heal between pulls.", steps = {"Mark of the Wild and Thorns (6) up.", "Wrath to pull, Moonfire (4) as it runs in.", "Melee it down to save mana.", "Rejuvenation or Healing Touch after the fight."}, stepIcons = {"spell_nature_regeneration", "spell_nature_abolishmagic", "inv_staff_08", "spell_nature_rejuvenation"}}, {level = 10, icon = "spell_nature_starfall", title = "Bear", range = "Levels 10–19", intro = "Do the Bear Form quest at 10 — it isn't on the trainer. Bear is your only form until 20.", steps = {"Moonfire to pull, then shift to Bear: Fight on the caster bar does both.", "Fight Bear: Maul each press, Enrage on the pull (12) and Faerie Fire to pull (18). Pack Bear opens with Demoralizing Roar.", "Swipe (16) when two or more are on you.", "Controller: the Bear macro on RT+A in Bear Form."}, stepIcons = {"spell_nature_starfall", "ability_druid_demoralizingroar", "inv_misc_monsterclaw_03", "inv_misc_note_01"}}, {level = 20, icon = "spell_nature_crystalball", title = "Cat", range = "Levels 20–29", intro = "Cat Form (20) is how you level from here. Train Omen of Clarity — in Forever it's a passive you train, not a talent.", steps = {"Buffs (LT+Up): Thorns, press again for Mark of the Wild; then Cat Form (RT+A). Omen of Clarity is passive.", "Claw ×3 → Rip; from 24 Rake → Claw ×3 → Ferocious Bite.", "Two or more mobs, or low health? Shift to Bear and Swipe.", "Heal up out of form between pulls."}, stepIcons = {"spell_nature_crystalball", "ability_druid_rake", "ability_racial_bearform", "spell_nature_healingtouch"}}, {level = 30, icon = "ability_druid_travelform", title = "Prowl & Ravage", range = "Levels 30–39", intro = "Travel Form (30) between quests. From 32, open from Prowl with Ravage behind the target.", steps = {"Travel Form outdoors, Cat Form indoors.", "Prowl Cat: Prowl, get behind, press again for Ravage (32), then Fight Cat.", "Leader of the Pack (35) is always on in forms."}, stepIcons = {"ability_druid_travelform", "ability_druid_ravage", "spell_nature_unyeildingstamina"}}, {level = 40, icon = "ability_druid_disembowel", title = "Dire Bear & Shifting Power", range = "Levels 40–60", intro = "Rend and Tear rewards keeping Rake up. Shifting Power (46) refills Energy from your mana.", steps = {"Always open the Fight sequence with Rake — the bleed powers Rend and Tear.", "Shifting Power (46) when Energy runs low: Prowl Cat casts it in combat.", "Barkskin (44) or Panic Bear (36) when a fight goes wrong; Dire Bear (40) for packs."}, stepIcons = {"ability_druid_disembowel", "spell_druid_displacement", "spell_nature_stoneclawtotem"}}}, spec = "Feral", guide = "Feral Druid"},
  PALADIN = {macros = {
    {name = "Fight", title = "Holy Strike + Judgement", icon = "classicon_paladin", lo = 1, hi = 60,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/startattack [harm,nodead]\n/cast [harm,nodead] Holy Strike\n/cast [harm,nodead] Judgement", pad = "RT+A", kb = "1",
     tips = {"Each press: Holy Strike when it is ready, with Judgement riding along on the same press (it is off the global cooldown) if a seal is up and the enemy is within 10 yards.", "While Holy Strike cools down (10 sec) the press only keeps you swinging, and Judgement waits too. Judgement joins at 4, Holy Strike at 6.", "After a kill one press selects the nearest enemy. Improved Judgement 2/2 (from 19) has Judgement ready 2 sec early: Seal, Stun, Pack and Exorcism carry it as well."}},
    {name = "Seal", title = "Seal of Righteousness + Judgement", icon = "ability_thunderbolt", lo = 1, hi = 19,
     body = "#showtooltip Seal of Righteousness\n/cast Seal of Righteousness\n/cast [harm,nodead] Judgement", pad = "RT+Y", kb = "4",
     tips = {"Before each pull and when your seal fades (30 sec): Seal of Righteousness, with Judgement riding along when it is ready and the enemy is within 10 yards.", "Pressed at 10 yards it seals and opens the pull with Judgement. Judgement doesn't use up the seal in Forever, so one seal per fight is usually enough.", "Seal of Command replaces it at 20."}},
    {name = "Seal", title = "Seal of Command + Judgement", icon = "ability_warrior_innerrage", lo = 20, hi = 39,
     body = "#showtooltip Seal of Command\n/cast Seal of Command\n/cast [harm,nodead] Judgement", pad = "RT+Y", kb = "4",
     tips = {"Before each pull and when your seal fades (30 sec): Seal of Command, with Judgement riding along when it is ready and the enemy is within 10 yards.", "Each press costs a seal's mana, so don't mash it: Fight carries Judgement in between.", "From 40 this button swaps between Command and Righteousness for Unsealed Wrath."}},
    {name = "Seal", title = "Seal swap + Judgement", icon = "ability_warrior_innerrage", lo = 40, hi = 60,
     body = "#showtooltip\n/castsequence reset=combat Seal of Command, Seal of Righteousness\n/cast [harm,nodead] Judgement", pad = "RT+Y", kb = "4",
     tips = {"The first press of each fight is Seal of Command, the next Righteousness, then Command again. Judgement rides along when it is ready.", "Unsealed Wrath: your swings store copies of the old seal (up to 3) and the first hit with the new one releases them. Pressing it each time Judgement is ready keeps both seals working.", "Every press costs a seal's mana. Short on mana? Press it only when the seal fades."}},
    {name = "Pack", title = "Consecration + Judgement", icon = "spell_holy_innerfire", lo = 20, hi = 60,
     body = "#showtooltip Consecration\n/startattack [harm,nodead]\n/cast [harm,nodead][combat] Consecration\n/cast [harm,nodead] Judgement", pad = "RT+B", kb = "2",
     tips = {"Two or more enemies on you: Consecration under your feet (Holy damage for 8 sec, extra on the first 4 that enter), with Judgement riding along when it is ready.", "8 sec cooldown; while it cools down the press does nothing, so go back to Fight. It costs a lot of mana: save it for packs."}},
    {name = "Exorcism", title = "Exorcism + Judgement", icon = "spell_holy_excorcism_02", lo = 20, hi = 60,
     body = "#showtooltip Exorcism\n/startattack [harm,nodead]\n/cast [harm,nodead] Exorcism\n/cast [harm,nodead] Judgement", pad = "RT+X", kb = "3",
     tips = {"Undead and Demons only: a big instant Holy hit from range, 15 sec cooldown. A good opener and a second strike between Holy Strikes.", "Judgement rides along when it is ready. On any other enemy the press does nothing."}},
    {name = "Finish", title = "Hammer of Wrath", icon = "ability_thunderclap", lo = 44, hi = 46,
     body = "#showtooltip Hammer of Wrath\n/cast [@mouseover,harm,nodead][harm,nodead] Hammer of Wrath", pad = "RT+Right", kb = "6",
     tips = {"Lights up on an enemy at 20% health or less: a big Holy hit from range, 6 sec cooldown. Great on runners. With a mouse it hits the enemy under your cursor.", "Champion of the Light shortens its cast; at 5/5 (47) it is instant and Judgement joins this button."}},
    {name = "Finish", title = "Hammer of Wrath + Judgement", icon = "ability_thunderclap", lo = 47, hi = 60,
     body = "#showtooltip Hammer of Wrath\n/cast [@mouseover,harm,nodead][harm,nodead] Hammer of Wrath\n/cast [@mouseover,harm,nodead][harm,nodead] Judgement", pad = "RT+Right", kb = "6",
     tips = {"Lights up on an enemy at 20% health or less: an instant Holy hit from range (Champion of the Light 5/5), 6 sec cooldown, with Judgement riding along on the same enemy when it is ready.", "Above 20% the press does nothing. With a mouse it hits the enemy under your cursor."}},
    {name = "Heal up", title = "Holy Light", icon = "spell_holy_holybolt", lo = 1, hi = 19,
     body = "#showtooltip Holy Light\n/cast [@mouseover,help,nodead][help,nodead][@targettarget,help,nodead][@player] Holy Light", pad = "LT+A", kb = "Q",
     tips = {"Heals the friend under your mouse, else your friendly target, else whoever your enemy target is hitting, else you. Solo with an enemy selected, that is you.", "Heal between fights instead of eating. Flash of Light joins at 20 for heals in combat."}},
    {name = "Heal up", title = "Flash of Light / Holy Light", icon = "spell_holy_flashheal", lo = 20, hi = 60,
     body = "#showtooltip\n/cast [combat,@mouseover,help,nodead][combat,help,nodead][combat,@targettarget,help,nodead][combat,@player] Flash of Light; [@mouseover,help,nodead][help,nodead][@targettarget,help,nodead][@player] Holy Light", pad = "LT+A", kb = "Q",
     tips = {"In combat: Flash of Light, the quick 1.5 sec heal. Out of combat: Holy Light, the big heal that fills you up in one cast.", "Either goes to the friend under your mouse, else your friendly target, else whoever your enemy target is hitting, else you."}},
    {name = "Panic", title = "Divine Protection", icon = "spell_holy_restoration", lo = 6, hi = 33,
     body = "#showtooltip Divine Protection\n/stopcasting\n/cast Divine Protection", pad = "LT+X", kb = "F",
     tips = {"Immune to physical attacks and spells for 6 sec (8 from 18), but you can't attack. It cuts off a heal you are casting so the shield goes up at once; then heal with Heal up.", "5 min cooldown and Forbearance for 1 min. Pressed while it cools down it still stops your cast. Lay on Hands (10) is in the spellbook for the last resort."}},
    {name = "Panic", title = "Divine Shield", icon = "spell_holy_divineintervention", lo = 34, hi = 60,
     body = "#showtooltip Divine Shield\n/stopcasting\n/cast Divine Shield", pad = "LT+X", kb = "F",
     tips = {"Immune to all damage for 10 sec (12 from 50), but your damage is halved: heal yourself inside it with Heal up. It cuts off a cast in progress so it goes up at once.", "Shares its 5 min cooldown with Divine Protection, so nothing backs it up but Lay on Hands. Pressed while it cools down it still stops your cast."}},
    {name = "Stun", title = "Hammer of Justice + Judgement", icon = "spell_holy_sealofmight", lo = 8, hi = 60,
     body = "#showtooltip Hammer of Justice\n/cast [@mouseover,harm,nodead][harm,nodead] Hammer of Justice\n/cast [@mouseover,harm,nodead][harm,nodead] Judgement", pad = "LT+Y", kb = "R",
     tips = {"Stuns your target, or the enemy under your mouse, for 3 sec (6 by 54): stop a cast or a runner. 1 min cooldown, 10 yards.", "Judgement rides along on the same enemy when it is ready. With Seal of Command (20) a Judgement on a stunned enemy does double damage."}},
    {name = "Cleanse", title = "Purify", icon = "spell_holy_purify", lo = 8, hi = 41,
     body = "#showtooltip Purify\n/cast [@mouseover,help,nodead][help,nodead][@player] Purify", pad = "LT+Right", kb = "Shift+Q",
     tips = {"Removes 1 poison and 1 disease from the friend under your mouse, else your friendly target, else you, so you don't have to change target mid-fight.", "Cleanse replaces it at 42 and removes magic too."}},
    {name = "Cleanse", title = "Cleanse", icon = "spell_holy_renew", lo = 42, hi = 60,
     body = "#showtooltip Cleanse\n/cast [@mouseover,help,nodead][help,nodead][@player] Cleanse", pad = "LT+Right", kb = "Shift+Q",
     tips = {"Removes 1 poison, 1 disease and 1 magic effect from the friend under your mouse, else your friendly target, else you."}},
  }, plan = {{name = "Benediction", tree = "Retribution", from = 10, to = 14, why = "Opens at 10. Seals, Judgement and Holy Strike are all instant, so 5/5 makes your whole rotation 10% cheaper — mana is your leveling bottleneck.", more = "2% cheaper per rank.", max = 5, icon = "spell_frost_windwalkon"}, {name = "Conviction", tree = "Retribution", from = 15, to = 17, why = "Earliest it opens (row 2, level 15). +2% crit per rank on melee, seals, Judgement and Holy Strike — 6% at 3/3, and Vengeance at 30 feeds on crits.", more = "+2% more crit.", max = 3, icon = "spell_holy_retributionaura"}, {name = "Improved Judgement", tree = "Retribution", from = 18, to = 19, why = "Judgement cooldown 10 → 8 sec at 2/2: about one extra Judgement every 40 sec, and Sanctified Judgement refunds mana on each one.", more = "8 sec at 2/2.", max = 2, icon = "spell_holy_righteousfury"}, {name = "Seal of Command", tree = "Retribution", from = 20, to = 20, why = "Earliest it opens (row 3, level 20). Procs Holy damage worth 70% of weapon damage — best on a slow two-hander — and its Judgement deals about 49 at 20 (71 by 28), double on stunned targets. Replaces Seal of Righteousness.", more = "", max = 1, icon = "ability_warrior_innerrage"}, {name = "Pursuit of Justice", tree = "Retribution", from = 21, to = 22, why = "+8% then +15% run and mount speed, always on — the best quality-of-life talent for questing. Doesn't stack with other speed effects.", more = "15% at 2/2.", max = 2, icon = "spell_holy_persuitofjustice"}, {name = "Sanctified Judgement", tree = "Retribution", from = 23, to = 25, why = "Judgement has a 33/66/100% chance to refund 20/40/60% of your seal's mana. At 3/3 every Judgement refunds 60%.", more = "Bigger, surer refund.", max = 3, icon = "ability_paladin_judgementblue"}, {name = "Sacred Arbiter", tree = "Retribution", from = 26, to = 26, why = "Row 4 (opens at 25). Holy Strike +20% damage, and each Holy Strike refreshes all your Judgement effects on the target.", more = "", max = 1, icon = "inv_sword_08"}, {name = "Two-Handed Weapon Specialization", tree = "Retribution", from = 27, to = 29, why = "+2/4/6% Physical and Holy damage with a two-hander (the 2 Nov notes added Holy), plus 7/14/20% less threat in groups.", more = "+2% more.", max = 3, icon = "inv_hammer_04"}, {name = "Vengeance", tree = "Retribution", from = 30, to = 32, why = "Earliest it opens (row 5, level 30; needs Seal of Command). Each crit gives +1/2/3% Physical and Holy damage for 30 sec, stacking 5 times — +15% at 3/3. With 6% Conviction it stays up.", more = "+1% more per stack.", max = 3, icon = "ability_racial_avatar"}, {name = "Repentance", tree = "Retribution", from = 33, to = 33, why = "6-sec incapacitate on a Humanoid add (1 min cooldown, damage breaks it). Also required for Unsealed Wrath at 40.", more = "", max = 1, icon = "spell_holy_prayerofhealing"}, {name = "Vindication", tree = "Retribution", from = 34, to = 36, why = "Your melee hits can cut the target's Attack Power for 30 sec — less damage taken every fight.", more = "Stronger weaken.", max = 3, icon = "spell_holy_vindication"}, {name = "Champion of the Light", tree = "Retribution", from = 37, to = 39, why = "Row 6 (opens at 35). Adds 12% of your Intellect per rank as spell damage — seals, Judgement and Consecration hit harder — and cuts Hammer of Wrath's cast by 0.2 sec per rank.", more = "+12% of Intellect.", max = 5, icon = "ability_paladin_enlightenedjudgements"}, {name = "Unsealed Wrath", tree = "Retribution", from = 40, to = 40, why = "Earliest it opens (row 7, level 40; needs Repentance). Each swing stores a copy of your Seal for 15 sec (up to 3); your next hit with a different Seal releases them, each with its normal proc chance.", more = "", max = 1, icon = "spell_holy_blessedresillience"}, {name = "Divine Strength", tree = "Holy", from = 41, to = 45, why = "Holy row 1, no prerequisites. +2% Strength per rank, 10% at 5/5 — more Attack Power on every swing.", more = "+2% more.", max = 5, icon = "ability_golemthunderclap"}, {name = "Champion of the Light", tree = "Retribution", from = 46, to = 47, why = "Finish Champion of the Light: 60% of your Intellect as spell damage, and Hammer of Wrath (44) becomes instant.", more = "", max = 5, icon = "ability_paladin_enlightenedjudgements"}, {name = "Reverence", tree = "Holy", from = 48, to = 49, why = "Holy row 2, opened by your 5 Divine Strength points. 15/30% of your mana regen keeps going while casting — fewer drink breaks.", more = "30% at 2/2.", max = 2, icon = "spell_holy_divineillumination"}, {name = "Improved Seals", tree = "Holy", from = 50, to = 54, why = "+3% per rank to Seal and Judgement damage — 15% at 5/5, covering Seal of Command procs and every Judgement.", more = "+3% more.", max = 5, icon = "ability_thunderbolt"}, {name = "Divine Intellect", tree = "Protection", from = 55, to = 59, why = "Protection row 1. +2% Intellect per rank (10% at 5/5): more mana, and more spell damage through Champion of the Light.", more = "+2% more.", max = 5, icon = "spell_nature_sleep"}, {name = "Precision", tree = "Protection", from = 60, to = 60, why = "Protection row 2, opened by Divine Intellect. +1% melee hit — fewer misses on level-60 mobs.", more = "", max = 3, icon = "ability_rogue_ambush"}}, train = {{level = 1, spells = {"Seal of Righteousness (Rank 1)", "Devotion Aura (Rank 1)", "Holy Light (Rank 1)"}, notes = {"Your seal until Seal of Command at 20.", "Armor aura.", "Slow, big heal between fights."}, icons = {"ability_thunderbolt", "spell_holy_devotionaura", "spell_holy_holybolt"}}, {level = 4, spells = {"Blessing of Might (Rank 1)", "Judgement"}, notes = {"Attack Power — lasts an hour.", "No longer eats your seal in Forever. 10 sec cooldown, 10 yd range."}, icons = {"spell_holy_fistofjustice", "spell_holy_righteousfury"}}, {level = 6, spells = {"Holy Strike (Rank 1)", "Divine Protection (Rank 1)", "Holy Light (Rank 2)", "Seal of the Crusader (Rank 1)"}, notes = {"New: instant strike, 10 sec cooldown.", "