Group buff — costs a Symbol of Kings.", "Situational."}, icons = {"ability_warrior_innerrage", "classicon_paladin", "spell_holy_innerfire", "ability_thunderclap", "spell_holy_fistofjustice", "spell_holy_holybolt", "spell_holy_excorcism_02", "spell_holy_devotionaura", "spell_holy_excorcism", "spell_holy_resurrection", "spell_holy_sealofwisdom", "spell_holy_healingaura", "spell_holy_greaterblessingofkings", "spell_holy_greaterblessingofwisdom", "spell_magic_greaterblessingofkings", "spell_fire_sealoffire"}}}, br = {{level = 1, icon = "ability_thunderbolt", title = "Before Talents", range = "Levels 1–9", intro = "Seal, Judge, swing. Grab the biggest two-handed weapon you can — Paladin damage scales with slow, heavy hits.", steps = {"Seal of Righteousness on before every fight.", "Blessing of Might (4) and Devotion Aura on.", "Judgement (4) once you're in range — in Forever it no longer eats your seal.", "Holy Strike (6) every 10 sec.", "Holy Light yourself between fights instead of eating."}, stepIcons = {"ability_thunderbolt", "spell_holy_fistofjustice", "spell_holy_righteousfury", "classicon_paladin", "spell_holy_holybolt"}}, {level = 10, icon = "spell_holy_auraoflight", title = "Seal, Judge, Strike", range = "Levels 10–19", intro = "Benediction makes all of this cheaper. Retribution Aura (16) hurts everything that hits you.", steps = {"Retribution Aura from 16.", "Seal → Judgement → Holy Strike, then swing. Re-seal when it fades.", "Hammer of Justice to stop a caster or runner.", "Running dry? Swap Might for Blessing of Wisdom (14).", "Controller: Seal (RT+Y) puts your seal up and judges; Fight (RT+A) casts Holy Strike with Judgement riding along."}, stepIcons = {"spell_holy_auraoflight", "spell_holy_righteousfury", "spell_holy_sealofmight", "spell_holy_sealofwisdom", "inv_misc_note_01"}}, {level = 20, icon = "ability_warrior_innerrage", title = "Seal of Command", range = "Levels 20–29", intro = "Seal of Command (20) is your leveling seal for the rest of the game. Consecration and Blessing of Kings are trainable at 20 in Forever.", steps = {"From 20 your Seal button (RT+Y) casts Seal of Command; Fight keeps Holy Strike and Judgement going.", "Stun (LT+Y) casts Hammer of Justice with Judgement on the same press: Command's Judgement does double damage to a stunned enemy.", "Consecration (20) on 2+ mobs.", "Flash of Light (20) for quick top-ups.", "Pursuit of Justice (21–22): 15% faster everywhere."}, stepIcons = {"ability_warrior_innerrage", "spell_holy_sealofmight", "spell_holy_innerfire", "spell_holy_flashheal", "spell_holy_persuitofjustice"}}, {level = 30, icon = "spell_holy_prayerofhealing", title = "Vengeance", range = "Levels 30–39", intro = "Vengeance stacks damage after every crit. Repentance (33) handles a Humanoid add.", steps = {"Repentance an add (6 sec, damage breaks it) while you open on the first mob.", "Divine Shield (34) when a pull goes wrong: it halves your damage, so heal up inside it. Panic (LT+X) switches to it at 34.", "Exorcism (RT+X) on Undead and Demons."}, stepIcons = {"spell_holy_prayerofhealing", "spell_holy_divineintervention", "spell_holy_excorcism_02"}}, {level = 40, icon = "spell_holy_blessedresillience", title = "Unsealed Wrath", range = "Levels 40–60", intro = "Your hits store copies of your seal for 15 sec (up to 3). Your next hit with a different seal releases them, each with its normal proc chance. Hammer of Wrath (44) finishes mobs under 20%.", steps = {"Seal (RT+Y) now swaps Command and Righteousness on each press, with Judgement riding along: press it when Judgement is ready and your next hit releases the stored copies.", "Finish (RT+→): Hammer of Wrath below 20% health.", "Packs: Pack (RT+B) for Consecration, then Fight for Holy Strike."}, stepIcons = {"spell_holy_blessedresillience", "ability_thunderclap", "spell_holy_innerfire"}}}, spec = "Retribution", guide = "Retribution Paladin"},
  PRIEST = {macros = {
    {name = "Fight", title = "Fight", icon = "spell_holy_holysmite", lo = 1, hi = 3,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/castsequence [equipped:Wands,nochanneling:Shoot] reset=target Smite, Shoot\n/cast [noequipped:Wands] Smite", pad = "RT+A", kb = "1",
     tips = {"Each press: Smite. With a wand on: Smite to pull, then your wand (Shoot). Pressing again while the wand shoots does nothing, so it never switches the wand off.", "No living enemy targeted: the press picks the nearest one first, so RT+A / 1 also finds the next mob after a kill."}},
    {name = "Fight", title = "Fight", icon = "spell_shadow_shadowwordpain", lo = 4, hi = 9,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/castsequence [equipped:Wands,nochanneling:Shoot] reset=target Smite, Shadow Word: Pain, Shoot\n/castsequence [noequipped:Wands] reset=target Smite, Shadow Word: Pain, Smite, Smite", pad = "RT+A", kb = "1",
     tips = {"Each press, in order: Smite to pull, Shadow Word: Pain (4), then your wand. Without a wand: Smite, Pain, then Smite again.", "A new target starts over at Smite. While the wand shoots a press does nothing, so you can mash RT+A / 1.", "No living enemy targeted: the press picks the nearest one first."}},
    {name = "Fight", title = "Fight", icon = "spell_shadow_unholyfrenzy", lo = 10, hi = 19,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/cast [nocombat] Mind Blast\n/castsequence [equipped:Wands,nochanneling:Shoot] reset=target Shadow Word: Pain, Shoot\n/castsequence [noequipped:Wands] reset=target Shadow Word: Pain, Smite, Smite", pad = "RT+A", kb = "1",
     tips = {"Out of combat the first press is Mind Blast (10), your pull. In combat: Shadow Word: Pain, then your wand (Smite without one). A new target starts over.", "Mind Blast has an 8 sec cooldown: pull again before it is back and the press waits for it (a few seconds at most).", "Mid-fight Mind Blast is on Blast (RT+X / 3): press it whenever it lights up.", "While the wand shoots a press does nothing, so it never switches the wand off. In a group let the tank grab the mob first: Mind Blast makes a lot of threat."}},
    {name = "Fight", title = "Fight", icon = "spell_shadow_siphonmana", lo = 20, hi = 39,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/cast [nocombat] Mind Blast\n/castsequence [nochanneling] reset=target Shadow Word: Pain, Mind Flay, Mind Flay, Mind Flay, Mind Flay, Mind Flay, Mind Flay", pad = "RT+A", kb = "1",
     tips = {"Out of combat: Mind Blast to pull. In combat: Shadow Word: Pain, then Mind Flay six times (about 18 sec), then Pain again. A new target starts over.", "No cooldown inside the sequence, so it never stalls, and a press never cuts a Mind Flay short: mash RT+A / 1. Mind Flay reaches 20 yd (24 with Shadow Reach).", "Cooldowns stay on their own keys: Mind Blast on Blast (RT+X / 3), Devouring Plague (20) and Vampiric Embrace (25) from your bar on tough mobs.", "Mind Blast cooling down when you pull: the press waits for it (a few seconds at most)."}},
    {name = "Fight", title = "Fight", icon = "spell_shadow_shadowform", lo = 40, hi = 60,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/cast [noform] Shadowform; [nocombat] Mind Blast\n/castsequence [nochanneling] reset=target Shadow Word: Pain, Mind Flay, Mind Flay, Mind Flay, Mind Flay, Mind Flay, Mind Flay", pad = "RT+A", kb = "1",
     tips = {"Out of Shadowform the first press puts it back on (40% of base mana, one global cooldown). Then as before: Mind Blast to pull, Shadow Word: Pain, Mind Flay six times.", "No cooldown inside the sequence, so it never stalls, and a press never cuts a Mind Flay short: mash RT+A / 1.", "Mind Blast (Blast, RT+X / 3), Devouring Plague and Vampiric Embrace: press them when they light up. In the form only healing spells are blocked."}},
    {name = "Blast", title = "Mind Blast", icon = "spell_shadow_unholyfrenzy", lo = 10, hi = 60,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/cast [harm,nodead] Mind Blast", pad = "RT+X", kb = "3",
     tips = {"One press: Mind Blast. With no living enemy targeted it picks the nearest one first.", "8 sec cooldown (7 at 34, 5.5 at 46 with Improved Mind Blast): press it whenever it lights up. Fight already opens with it."}},
    {name = "Finish", title = "Shadow Word: Death", icon = "spell_shadow_demonicfortitude", lo = 32, hi = 60,
     body = "#showtooltip\n/cast [harm,nodead] Shadow Word: Death", pad = "RT+B", kb = "2",
     tips = {"One press: Shadow Word: Death on your target. 18 sec cooldown.", "Only when the hit will kill: if the target survives, you take 30% of your maximum health.", "From 41 Early Demise adds 30% crit chance on targets at or below 20% health: exactly when to press it."}},
    {name = "Silence", title = "Silence", icon = "spell_shadow_impphaseshift", lo = 32, hi = 60,
     body = "#showtooltip\n/stopcasting\n/cast [@mouseover,harm,nodead][harm,nodead] Silence", pad = "RT+Y", kb = "4",
     tips = {"One press: stops your own cast (Mind Flay too) and Silences the enemy under your mouse, else your target: 5 sec silence, 3 sec interrupt. 45 sec cooldown.", "Keyboard: hover a second caster to silence it without changing target."}},
    {name = "Burst", title = "Inner Focus + Mind Blast", icon = "spell_frost_windwalkon", lo = 57, hi = 60,
     body = "#showtooltip Inner Focus\n/targetenemy [noharm][dead]\n/cast Inner Focus\n/cast [harm,nodead] Mind Blast", pad = "RT+Up", kb = "5",
     tips = {"One press: Inner Focus, then Mind Blast: free, and 25% more likely to crit. Save it for a tough mob or the second mob of a pull.", "Inner Focus has a 3 min cooldown. Until it is back the button does nothing (it shows the Inner Focus cooldown): use Blast (RT+X / 3)."}},
    {name = "Shield", title = "Shield yourself", icon = "spell_holy_powerwordshield", lo = 6, hi = 60,
     body = "#showtooltip\n/cast [@player] Power Word: Shield", pad = "LT+A", kb = "Q",
     tips = {"One press: Power Word: Shield on you, even with an enemy or a friend targeted. Shield before the pull: casts aren't pushed back while it holds.", "Not ready: 4 sec cooldown, and Weakened Soul stops a new shield on you for 15 sec."}},
    {name = "Heal up", title = "Heal up", icon = "spell_holy_lesserheal", lo = 1, hi = 15,
     body = "#showtooltip\n/cast [@mouseover,help,nodead][help,nodead][@targettarget,help,nodead][@player] Lesser Heal", pad = "LT+B", kb = "E",
     tips = {"One press: Lesser Heal on the friend under your mouse, else your friendly target, else whoever your enemy target is hitting, else you. Solo that is you.", "Heal (16) takes this button over, Flash Heal at 20."}},
    {name = "Heal up", title = "Heal up", icon = "spell_holy_heal02", lo = 16, hi = 19,
     body = "#showtooltip\n/cast [@mouseover,help,nodead][help,nodead][@targettarget,help,nodead][@player] Heal", pad = "LT+B", kb = "E",
     tips = {"One press: Heal (3 sec cast) on the friend under your mouse, else your friendly target, else whoever your enemy target is hitting, else you. Solo that is you.", "Flash Heal takes this button over at 20."}},
    {name = "Heal up", title = "Heal up", icon = "spell_holy_flashheal", lo = 20, hi = 39,
     body = "#showtooltip\n/cast [@mouseover,help,nodead][help,nodead][@targettarget,help,nodead][@player] Flash Heal", pad = "LT+B", kb = "E",
     tips = {"One press: Flash Heal (1.5 sec cast) on the friend under your mouse, else your friendly target, else whoever your enemy target is hitting, else you. Solo that is you.", "Between pulls Renew or Heal from your bar cost less mana."}},
    {name = "Heal up", title = "Heal up", icon = "spell_holy_flashheal", lo = 40, hi = 60,
     body = "#showtooltip\n/cancelform\n/cast [@mouseover,help,nodead][help,nodead][@targettarget,help,nodead][@player] Flash Heal", pad = "LT+B", kb = "E",
     tips = {"One press: leaves Shadowform (you can't heal in it), then Flash Heal on the friend under your mouse, else your friendly target, else whoever your enemy target is hitting, else you. Solo that is you.", "Every press drops the form, even when the heal can't go (no mana). Fight (RT+A / 1) puts it back on: 40% of base mana, so heal only when Shield and Vampiric Embrace aren't enough."}},
    {name = "Buffs", title = "Buffs", icon = "spell_holy_innerfire", lo = 12, hi = 29,
     body = "#showtooltip\n/castsequence [@mouseover,help,nodead][help,nodead][@player] reset=20 Inner Fire, Power Word: Fortitude", pad = "LT+Up", kb = "Shift+1",
     tips = {"Press 1: Inner Fire on you. Press 2: Power Word: Fortitude on the friend under your mouse or your friendly target, else you.", "No cooldowns, so it never stalls. 20 sec after your last press it starts over at Inner Fire. Divine Spirit joins at 30."}},
    {name = "Buffs", title = "Buffs", icon = "spell_holy_innerfire", lo = 30, hi = 60,
     body = "#showtooltip\n/castsequence [@mouseover,help,nodead][help,nodead][@player] reset=20 Inner Fire, Power Word: Fortitude, Divine Spirit", pad = "LT+Up", kb = "Shift+1",
     tips = {"Press 1: Inner Fire on you. Press 2: Power Word: Fortitude, press 3: Divine Spirit, both on the friend under your mouse or your friendly target, else you.", "No cooldowns, so it never stalls. 20 sec after your last press it starts over at Inner Fire."}},
  }, plan = {{name = "Spirit Tap", tree = "Shadow", from = 10, to = 14, why = "The leveling talent: +20% chance per rank that a kill doubles your Spirit for 15 sec and keeps 50% of mana regen going while casting. 100% at 5/5 (non-trivial kills).", more = "+20% more chance.", max = 5, icon = "spell_shadow_requiem"}, {name = "Improved Shadow Word: Pain", tree = "Shadow", from = 15, to = 16, why = "Earliest row 2 opens. Shadow Word: Pain lasts 24 sec instead of 18 at 2/2 — one cast covers the whole fight.", more = "", max = 2, icon = "spell_shadow_shadowwordpain"}, {name = "Shadow Reach", tree = "Shadow", from = 17, to = 18, why = "+10% range per rank on offensive Shadow spells. At 2/2 Mind Blast and Pain reach 36 yd, Mind Flay 24 yd.", more = "", max = 2, icon = "spell_shadow_chilltouch"}, {name = "Shadow Focus", tree = "Shadow", from = 19, to = 19, why = "+1% Shadow hit — and the 10th point, which opens Mind Flay at 20.", more = "", max = 5, icon = "spell_shadow_burningspirit"}, {name = "Mind Flay", tree = "Shadow", from = 20, to = 20, why = "Earliest it opens (row 3, 10 points). Your filler: 45 mana, 63 Shadow damage over 3 sec and a 50% slow. 20 yd range (24 with Shadow Reach).", more = "", max = 1, icon = "spell_shadow_siphonmana"}, {name = "Improved Mind Flay", tree = "Shadow", from = 21, to = 22, why = "Each Mind Flay tick deals 10% more than the last per rank (20% at 2/2) — let it channel fully.", more = "", max = 2, icon = "spell_shadow_soulleech_2"}, {name = "Shadow Focus", tree = "Shadow", from = 23, to = 24, why = "Shadow Focus to 3/5: +3% Shadow hit, fewer resisted Mind Blasts. Brings you to 15 points for row 4.", more = "", max = 5, icon = "spell_shadow_burningspirit"}, {name = "Vampiric Embrace", tree = "Shadow", from = 25, to = 25, why = "Earliest it opens (row 4, 15 points). 40 mana, 30 sec cooldown: heals you for 20% of your Shadow damage for 30 sec. Required for Shadowform.", more = "", max = 1, icon = "spell_shadow_unsummonbuilding"}, {name = "Shadow Weaving", tree = "Shadow", from = 26, to = 28, why = "At 3/3 every Shadow spell adds +2% Shadow damage taken from you, 5 stacks (+10%) for 15 sec.", more = "", max = 3, icon = "spell_shadow_blackplague"}, {name = "Shadow Focus", tree = "Shadow", from = 29, to = 29, why = "Shadow Focus 4/5 (+4% hit) — the 20th point, which opens row 5 at 30.", more = "", max = 5, icon = "spell_shadow_burningspirit"}, {name = "Devouring Contagion", tree = "Shadow", from = 30, to = 31, why = "Earliest it opens (row 5, 20 points). At 2/2 Devouring Plague costs 50% less, and a target that dies with it spreads it to 2 enemies within 10 yd.", more = "", max = 2, icon = "spell_shadow_devouringplague"}, {name = "Silence", tree = "Shadow", from = 32, to = 32, why = "Silence a caster: 5 sec silence plus a 3 sec interrupt, 45 sec cooldown.", more = "", max = 1, icon = "spell_shadow_impphaseshift"}, {name = "Improved Mind Blast", tree = "Shadow", from = 33, to = 34, why = "Mind Blast cooldown 8 → 7 sec at 2/5. Also the 25th point, which opens row 6 at 35.", more = "", max = 5, icon = "spell_shadow_unholyfrenzy"}, {name = "Darkness", tree = "Shadow", from = 35, to = 39, why = "Earliest it opens (row 6, 25 points). +2% Shadow damage per rank, +10% at 5/5.", more = "+2% more.", max = 5, icon = "spell_shadow_twilight"}, {name = "Shadowform", tree = "Shadow", from = 40, to = 40, why = "Earliest it opens (row 7, 30 points + Vampiric Embrace). Shadow spells cost 50% less, +10% Shadow damage, +100% Shadow crit bonus, 15% less physical damage taken. No healing spells in it.", more = "", max = 1, icon = "spell_shadow_shadowform"}, {name = "Early Demise", tree = "Shadow", from = 41, to = 42, why = "+15% Shadow Word: Death crit per rank (+30% at 2/2) on targets at or below 20% health — exactly when you use it.", more = "", max = 2, icon = "spell_shadow_demonicfortitude"}, {name = "Shadow Focus", tree = "Shadow", from = 43, to = 43, why = "Shadow Focus 5/5: +5% Shadow hit.", more = "", max = 5, icon = "spell_shadow_burningspirit"}, {name = "Improved Mind Blast", tree = "Shadow", from = 44, to = 46, why = "Improved Mind Blast to 5/5: Mind Blast cooldown 8 → 5.5 sec.", more = "-0.5 sec more.", max = 5, icon = "spell_shadow_unholyfrenzy"}, {name = "Twin Disciplines", tree = "Discipline", from = 47, to = 51, why = "Shadow's damage talents are done. Instant spells (Pain, Devouring Plague, Death) deal +1% per rank, +5% at 5/5.", more = "+1% more.", max = 5, icon = "spell_holy_sealofvengeance"}, {name = "Mental Strength", tree = "Discipline", from = 52, to = 56, why = "Earliest row 2 opens in Discipline. +2% total Intellect per rank (+10%): a bigger mana pool.", more = "+2% more.", max = 5, icon = "spell_nature_enchantarmor"}, {name = "Inner Focus", tree = "Discipline", from = 57, to = 57, why = "Earliest it opens (row 3, 10 Discipline points). 3 min cooldown: next spell free with +25% crit — Burst (RT+Up) pairs it with Mind Blast.", more = "", max = 1, icon = "spell_frost_windwalkon"}, {name = "Meditation", tree = "Discipline", from = 58, to = 60, why = "17/33/50% of mana regen keeps going while casting.", more = "", max = 3, icon = "spell_nature_sleep"}}, train = {{level = 1, spells = {"Smite", "Lesser Heal", "Power Word: Fortitude"}, notes = {"Early damage spell.", "Early heal.", "Stamina buff."}, icons = {"spell_holy_holysmite", "spell_holy_lesserheal", "spell_holy_wordfortitude"}}, {level = 4, spells = {"Shadow Word: Pain", "Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, notes = {"Your core DoT.", "Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, icons = {"spell_shadow_shadowwordpain", "inv_misc_book_09"}}, {level = 6, spells = {"Power Word: Shield", "Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devour