, Power Word: Shield and your heals every visit."}, notes = {"Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, icons = {"inv_misc_book_09"}}, {level = 56, spells = {"Prayer of Shadow Protection", "Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, notes = {"Group buff.", "Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, icons = {"spell_holy_prayerofshadowprotection", "inv_misc_book_09"}}, {level = 58, spells = {"Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, notes = {"Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, icons = {"inv_misc_book_09"}}, {level = 60, spells = {"Prayer of Spirit", "Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, notes = {"Group buff.", "Train the new ranks of Shadow Word: Pain, Mind Blast, Mind Flay (28+), Devouring Plague (28+), Shadow Word: Death (40+), Power Word: Shield and your heals every visit."}, icons = {"spell_holy_prayerofspirit", "inv_misc_book_09"}}}, br = {{level = 1, icon = "spell_holy_wordfortitude", title = "Before Talents", range = "Levels 1–9", intro = "Smite and wand early. Every Priest levels on a wand — buy or make the best one you can.", steps = {"Power Word: Fortitude and Inner Fire (12) up.", "Shadow Word: Pain (4), then Smite or wand.", "Power Word: Shield (6) when something reaches you.", "Finish with your wand to save mana."}, stepIcons = {"spell_holy_wordfortitude", "spell_shadow_shadowwordpain", "spell_holy_powerwordshield", "inv_wand_01"}}, {level = 10, icon = "spell_shadow_unholyfrenzy", title = "Mind Blast & Wand", range = "Levels 10–19", intro = "Spirit Tap refills mana after kills. Open with Mind Blast, DoT, then wand.", steps = {"Mind Blast from range → Shadow Word: Pain → wand.", "Shield when it reaches you; the shield also stops spell pushback.", "Psychic Scream (14) when two are on you.", "Controller: the Fight macro on RT+A does this order."}, stepIcons = {"spell_shadow_unholyfrenzy", "spell_holy_powerwordshield", "spell_shadow_psychicscream", "inv_misc_note_01"}}, {level = 20, icon = "spell_shadow_siphonmana", title = "Mind Flay", range = "Levels 20–29", intro = "Mind Flay (20) slows by 50% but reaches only 20 yd (24 with Shadow Reach). Devouring Plague (20) is trainable for every Priest: instant, 24 sec cooldown, heals you.", steps = {"Mind Blast from range → Pain → Mind Flay until it dies.", "Devouring Plague on tough mobs whenever it is off cooldown.", "Vampiric Embrace (25) on tough mobs for self-healing.", "Flash Heal (20) between pulls."}, stepIcons = {"spell_shadow_unholyfrenzy", "spell_shadow_devouringplague", "spell_shadow_unsummonbuilding", "spell_holy_flashheal"}}, {level = 30, icon = "spell_shadow_demonicfortitude", title = "Shadow Word: Death", range = "Levels 30–39", intro = "Shadow Word: Death (32) finishes low mobs — but if they survive it, you take 30% of your max health.", steps = {"Use Death only when the mob will die from it.", "Silence (32) casters: the Silence button (RT+Y) stops your cast first.", "Devouring Plague on packs — with Devouring Contagion (30–31) it jumps to 2 enemies within 10 yd when the target dies."}, stepIcons = {"spell_shadow_demonicfortitude", "spell_shadow_impphaseshift", "spell_shadow_devouringplague"}}, {level = 40, icon = "spell_shadow_shadowform", title = "Shadowform", range = "Levels 40–60", intro = "Shadowform (40) halves Shadow spell costs and adds damage. You can't heal in it — Shield and Vampiric Embrace keep you alive.", steps = {"Fight (RT+A) puts Shadowform back on; Heal up (LT+B) drops it to heal, so heal between pulls.", "Fight: Mind Blast → Pain → Mind Flay. Blast (RT+X) and Devouring Plague whenever they light up; Mind Blast is back every 5.5 sec at Improved Mind Blast 5/5.", "Shadow Word: Death to finish."}, stepIcons = {"spell_shadow_shadowform", "spell_shadow_shadowwordpain", "spell_shadow_demonicfortitude"}}}, spec = "Shadow", guide = "Shadow Priest"},
  ROGUE = {macros = {
    {name = "Fight", title = "Fight: Sinister Strike", icon = "spell_shadow_ritualofsacrifice", lo = 1, hi = 19,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/startattack [nostealth,harm,nodead]\n/cast [harm,nodead] Sinister Strike", pad = "RT+A", kb = "1",
     tips = {"Each press: Sinister Strike (1 combo point) with auto attack. Picks the nearest enemy when you have none or yours died. Spend the points with Finish (RT+B).", "From Stealth it opens with Sinister Strike: auto attack waits for it, so Stealth holds while you walk in.", "\"Not enough energy\": press again, it only waits for Energy."}},
    {name = "Fight", title = "Fight: Sinister Strike, Riposte", icon = "spell_shadow_ritualofsacrifice", lo = 20, hi = 23,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/startattack [nostealth,harm,nodead]\n/cast [harm,nodead] Sinister Strike\n/cast Riposte", pad = "RT+A", kb = "1",
     tips = {"Each press: Sinister Strike with auto attack. Spend the points with Finish (RT+B).", "Riposte rides along: after you parry it lights up and fires with your next Sinister Strike, because it is off the global cooldown. Unlit, it is simply skipped at the end.", "From Stealth it opens with Sinister Strike; Stealth holds while you walk in."}},
    {name = "Fight", title = "Fight: Sinister Strike, Shank", icon = "ability_theblackarrow", lo = 24, hi = 25,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/startattack [nostealth,harm,nodead]\n/castsequence [harm,nodead] reset=target Sinister Strike, Sinister Strike, Sinister Strike, Shank\n/cast Riposte", pad = "RT+A", kb = "1",
     tips = {"Sinister Strike three times, then Shank, then round again. A new target starts over.", "Shank is an off-hand strike that gives Energy back. Its 10 sec cooldown is over by the time the sequence gets back to it. It needs an off-hand weapon: without one the sequence stops at Shank.", "Riposte still rides along after a parry."}},
    {name = "Fight", title = "Fight: Cheap Shot, Sinister Strike", icon = "ability_cheapshot", lo = 26, hi = 38,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/startattack [nostealth,harm,nodead]\n/cast [stealth,harm,nodead] Cheap Shot\n/castsequence [nostealth,harm,nodead] reset=target Sinister Strike, Sinister Strike, Sinister Strike, Shank\n/cast Riposte", pad = "RT+A", kb = "1",
     tips = {"From Stealth: Cheap Shot (4 sec stun, 2 combo points). Then Sinister Strike three times, Shank, and round again. A new target starts over.", "Shank is an off-hand strike that gives Energy back. Its 10 sec cooldown is over by the time the sequence gets back to it. It needs an off-hand weapon: without one the sequence stops at Shank.", "Riposte rides along after a parry. Auto attack waits for Cheap Shot, so Stealth holds while you walk in."}},
    {name = "Fight", title = "Fight: Cheap Shot, Sinister Strike", icon = "ability_cheapshot", lo = 39, hi = 60,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/startattack [nostealth,harm,nodead]\n/cast [stealth,harm,nodead] Cheap Shot\n/castsequence [nostealth,harm,nodead] reset=target Sinister Strike, Sinister Strike, Shank\n/cast Riposte", pad = "RT+A", kb = "1",
     tips = {"With Flash of Steel 5/5 Shank is back every 8 sec and returns 30 Energy (40 from 44), so the sequence is now Sinister Strike twice, then Shank.", "If Shank is still cooling, the press waits a moment while your Energy fills up: nothing is lost.", "From Stealth: Cheap Shot. Riposte rides along after a parry. Shank needs an off-hand weapon."}},
    {name = "Finish", title = "Finish: Eviscerate", icon = "ability_rogue_eviscerate", lo = 1, hi = 9,
     body = "#showtooltip\n/cast [harm,dead] Redirect\n/startattack [harm,nodead]\n/cast [harm,nodead] Eviscerate", pad = "RT+B", kb = "2",
     tips = {"Press it at 3-5 combo points: Eviscerate. You can see your points on the target frame.", "Your target died with points still on it? Press Finish once on the corpse: Redirect keeps them for 15 sec, and your next hit on a new enemy gets them."}},
    {name = "Finish", title = "Finish: Slice and Dice, Eviscerate", icon = "ability_rogue_slicedice", lo = 10, hi = 60,
     body = "#showtooltip\n/cast [harm,dead] Redirect\n/startattack [harm,nodead]\n/castsequence [harm,nodead] reset=target Slice and Dice, Eviscerate", pad = "RT+B", kb = "2",
     tips = {"First Finish on each target: Slice and Dice (press it at 1-2 combo points). The next one: Eviscerate (press at 4-5). A long fight goes round again, which renews Slice and Dice.", "Target died with points left: Finish on the corpse casts Redirect (10 sec cooldown), then Fight on the next mob carries the points over.", "No cooldown on this button: \"not ready\" means Energy or combo points."}},
    {name = "Burst", title = "Burst: Blade Flurry", icon = "ability_warrior_punishingblow", lo = 30, hi = 39,
     body = "#showtooltip Blade Flurry\n/startattack [harm,nodead]\n/cast Blade Flurry\n/cast [combat] Evasion", pad = "RT+Y", kb = "3",
     tips = {"Two mobs on you: Blade Flurry (+20% attack speed, every hit also strikes a second mob, 15 sec), and in combat Evasion with it. Then keep pressing Fight.", "With Endurance both come back every 2 min, so they cool down together. While Blade Flurry cools down the button does nothing; before a pull it skips Evasion."}},
    {name = "Burst", title = "Burst: Blade Flurry, Adrenaline Rush", icon = "spell_shadow_shadowworddominate", lo = 40, hi = 60,
     body = "#showtooltip\n/startattack [harm,nodead]\n/castsequence reset=30 Blade Flurry, Adrenaline Rush\n/cast [combat] Evasion", pad = "RT+Y", kb = "3",
     tips = {"First press: Blade Flurry, with Evasion in combat. Second press: Adrenaline Rush (double Energy for 15 sec). Then Fight and Finish.", "Adrenaline Rush has a 5 min cooldown, Blade Flurry 2 min: when Rush is not back the second press does nothing. After 30 sec without a press it starts over at Blade Flurry.", "Want Adrenaline Rush alone on one elite while Blade Flurry cools down? Use the spellbook."}},
    {name = "Stop a cast", title = "Stop a cast: Gouge", icon = "ability_gouge", lo = 6, hi = 11,
     body = "#showtooltip Gouge\n/cast [@mouseover,harm,nodead][harm,nodead] Gouge", pad = "RT+X", kb = "4",
     tips = {"Gouges the enemy under your mouse, else your target: a 4 sec incapacitate that also stops its cast. It must face you, and any damage breaks it.", "10 sec cooldown. Kick takes over this button at 12."}},
    {name = "Stop a cast", title = "Stop a cast: Kick", icon = "ability_kick", lo = 12, hi = 60,
     body = "#showtooltip Kick\n/cast [@mouseover,harm,nodead][harm,nodead] Kick", pad = "RT+X", kb = "4",
     tips = {"Kicks the enemy under your mouse, else your target (on a controller: your target). It stops the cast and locks that spell school for 5 sec.", "10 sec cooldown, and in Forever it uses your 1 sec global cooldown. While it cools down, Gouge from the spellbook also stops a cast if the caster faces you."}},
    {name = "Stealth", title = "Stealth / Pick Pocket", icon = "ability_stealth", lo = 1, hi = 60,
     body = "#showtooltip\n/cast [nostealth] Stealth; [harm,nodead] Pick Pocket", pad = "LT+A", kb = "E",
     tips = {"Out of Stealth: Stealth. In Stealth: picks your target's pocket (from 4) instead of dropping Stealth, so a second press never breaks it.", "Stealth has a 10 sec cooldown in Forever and can't start in combat. To leave it, click the buff off."}},
    {name = "Escape", title = "Escape: Sprint", icon = "ability_rogue_sprint", lo = 10, hi = 21,
     body = "#showtooltip Sprint\n/cast Sprint\n/cast [combat,harm,nodead] Gouge", pad = "LT+Y", kb = "F",
     tips = {"Sprint: +50% speed for 15 sec. In combat it also Gouges your target (4 sec), which gives you a head start. Out of combat it is only Sprint, for travel.", "Sprint comes first: while it cools down the press does nothing. Vanish joins at 22."}},
    {name = "Escape", title = "Escape: Vanish", icon = "ability_vanish", lo = 22, hi = 60,
     body = "#showtooltip\n/stopattack\n/cast [combat] Vanish\n/cast Sprint", pad = "LT+Y", kb = "F",
     tips = {"In combat: stops your attacks, Vanish (out of the fight and into Stealth, uses a Flash Powder) and Sprint. Out of combat: only Sprint, for travel.", "While Vanish cools down (5 min) the in-combat press does nothing: use Sprint and Gouge from the spellbook then."}},
  }, plan = {{name = "Efficient Strikes", tree = "Combat", from = 10, to = 11, why = "Sinister Strike is your most-pressed button: 45 Energy drops to 42 now, 40 at 2/2.", more = "", max = 2, icon = "spell_shadow_ritualofsacrifice"}, {name = "Coup de Grace", tree = "Combat", from = 12, to = 14, why = "Eviscerate is your finisher — 20% more damage on every kill.", more = "More Eviscerate damage.", max = 3, icon = "ability_rogue_eviscerate"}, {name = "Deflection", tree = "Combat", from = 15, to = 17, why = "+6% parry: fewer hits taken, and it unlocks Riposte at 20.", more = "+2% more parry.", max = 3, icon = "ability_parry"}, {name = "Precision", tree = "Combat", from = 18, to = 19, why = "Forever Precision is 1% hit per rank (3 max, was 5%). Misses waste Energy.", more = "+1% more hit.", max = 3, icon = "ability_marksmanship"}, {name = "Riposte", tree = "Combat", from = 20, to = 20, why = "After a parry: 10 Energy, 150% weapon damage and a 6 sec disarm (6 sec cooldown). It is off the global cooldown in Forever, so Fight fires it with your next Sinister Strike.", more = "", max = 1, icon = "ability_warrior_challange"}, {name = "Precision", tree = "Combat", from = 21, to = 21, why = "Precision to 3/3: 3% hit.", more = "", max = 3, icon = "ability_marksmanship"}, {name = "Endurance", tree = "Combat", from = 22, to = 23, why = "Evasion and Sprint cooldowns −30% (−60% at 2/2): both back every 2 min instead of 5.", more = "Both now 2 min.", max = 2, icon = "spell_shadow_shadowward"}, {name = "Improved Sprint", tree = "Combat", from = 24, to = 24, why = "50% chance for Sprint to break snares (100% at 2/2 later).", more = "", max = 2, icon = "ability_rogue_sprint"}, {name = "Aggression", tree = "Combat", from = 25, to = 27, why = "Sinister Strike and Eviscerate deal 15% more — your two main attacks.", more = "+5% more.", max = 3, icon = "ability_racial_avatar"}, {name = "Weapon Expertise", tree = "Combat", from = 28, to = 29, why = "Attacks 1% less likely to be dodged or parried (2% at 2/2). Needs Precision 3/3.", more = "Now 2%.", max = 2, icon = "spell_holy_blessingofstrength"}, {name = "Blade Flurry", tree = "Combat", from = 30, to = 30, why = "Blade Flurry: 25 Energy, 2 min cooldown — +20% attack speed and hits a second mob for 15 sec.", more = "", max = 1, icon = "ability_warrior_punishingblow"}, {name = "Dual Wield Specialization", tree = "Combat", from = 31, to = 32, why = "Off-hand damage +50%. Your off-hand weapon hits on every auto attack.", more = "+25% more.", max = 2, icon = "ability_dualwield"}, {name = "Hack and Slash", tree = "Combat", from = 33, to = 34, why = "Weapon bonus: extra attacks with swords and axes, crit with daggers and fists, armor penetration with maces.", more = "Bigger weapon bonus.", max = 5, icon = "inv_sword_27"}, {name = "Flash of Steel", tree = "Combat", from = 35, to = 39, why = "Shank returns 15 Energy (25 at 44). Each rank adds +3 Energy and −0.4 sec cooldown: 5/5 = +15 Energy, every 8 sec.", more = "+3 Energy, −0.4 sec.", max = 5, icon = "ability_rogue_restlessblades"}, {name = "Adrenaline Rush", tree = "Combat", from = 40, to = 40, why = "The capstone: double Energy regeneration for 15 sec. Pair with Blade Flurry for huge burst.", more = "", max = 1, icon = "spell_shadow_shadowworddominate"}, {name = "Hack and Slash", tree = "Combat", from = 41, to = 43, why = "Finish Hack and Slash for the full weapon bonus.", more = "", max = 5, icon = "inv_sword_27"}, {name = "Flawless Execution", tree = "Combat", from = 44, to = 44, why = "Eviscerate costs 20 Energy instead of 35.", more = "", max = 1, icon = "inv_sword_35"}, {name = "Malice", tree = "Assassination", from = 45, to = 49, why = "Combat is done. +5% crit from the Assassination tree.", more = "+1% more crit.", max = 5, icon = "ability_racial_bloodrage"}, {name = "Remorseless Attacks", tree = "Assassination", from = 50, to = 51, why = "After a kill, your next Sinister Strike within 20 sec gets +20% crit (+40% at 2/2) — good for chain-pulling.", 