  WARLOCK = {macros = {
    {name = "Fight", title = "Fight (Immolate, Shadow Bolt)", icon = "spell_fire_immolation", lo = 1, hi = 3,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/petattack\n/castsequence [nochanneling:Drain Life/Drain Soul/Wrack/Health Funnel] reset=target Immolate, Shadow Bolt, Shadow Bolt, Shadow Bolt", pad = "RT+A", kb = "1",
     tips = {"Each press: sends your demon, then the next step: Immolate, then Shadow Bolt three times, then Immolate again.", "New target: starts over at the first step. No live enemy selected, or yours just died: the press picks the nearest enemy first.", "Mob nearly dead: finish it with the Wand (RT+Y) instead of starting the loop again."}},
    {name = "Fight", title = "Fight (Corruption, Immolate, Shadow Bolt)", icon = "spell_shadow_abominationexplosion", lo = 4, hi = 7,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/petattack\n/castsequence [nochanneling:Drain Life/Drain Soul/Wrack/Health Funnel] reset=target Corruption, Immolate, Shadow Bolt, Shadow Bolt", pad = "RT+A", kb = "1",
     tips = {"Each press: sends your demon, then Corruption, Immolate, Shadow Bolt twice, then back to Corruption.", "New target: starts over at the first step. No live enemy selected, or yours just died: the press picks the nearest enemy first.", "Mob nearly dead: let the DoTs tick and finish with the Wand (RT+Y) rather than looping back."}},
    {name = "Fight", title = "Fight (DoTs, Shadow Bolt)", icon = "spell_shadow_curseofsargeras", lo = 8, hi = 13,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/petattack\n/castsequence [nochanneling:Drain Life/Drain Soul/Wrack/Health Funnel] reset=target Corruption, Bane of Agony, Immolate, Shadow Bolt, Shadow Bolt", pad = "RT+A", kb = "1",
     tips = {"Each press: sends your demon, then Corruption, Bane of Agony, Immolate, Shadow Bolt twice, then back to Corruption.", "New target: starts over at the first step. No live enemy selected, or yours just died: the press picks the nearest enemy first.", "Mob nearly dead: don't loop back (Agony would go out again early). Wand (RT+Y) or Drain Soul (RT+B, 10+) instead."}},
    {name = "Fight", title = "Fight (DoTs, Drain Life)", icon = "spell_shadow_lifedrain02", lo = 14, hi = 30,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/petattack\n/castsequence [nochanneling:Drain Life/Drain Soul/Wrack/Health Funnel] reset=target Corruption, Bane of Agony, Immolate, Drain Life, Drain Life, Drain Life", pad = "RT+A", kb = "1",
     tips = {"Each press: sends your demon, then Corruption, Bane of Agony, Immolate, then Drain Life three times. Three drains last about as long as the DoTs, so the next press refreshes them.", "Pressing while Drain Life, Wrack, Drain Soul or Health Funnel channels does nothing, so mash it. It does stop your wand, so wand between steps. Stay within 20 yd for Drain Life.", "New target: starts over at the first step. No live enemy selected, or yours just died: the press picks the nearest enemy first."}},
    {name = "Fight", title = "Fight (DoTs, Siphon Life, Drain Life)", icon = "spell_shadow_requiem", lo = 31, hi = 39,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/petattack\n/castsequence [nochanneling:Drain Life/Drain Soul/Wrack/Health Funnel] reset=target Corruption, Bane of Agony, Siphon Life, Drain Life, Drain Life, Drain Life", pad = "RT+A", kb = "1",
     tips = {"Each press: Corruption, Bane of Agony, Siphon Life, then Drain Life three times, then refresh.", "Siphon Life replaces Immolate: a Shadow DoT that heals you and counts for Soul Siphon; Immolate does neither. Nightfall glow: Shadow Bolt from the spellbook is instant.", "Pressing while Drain Life, Wrack, Drain Soul or Health Funnel channels does nothing, so mash it. It does stop your wand, so wand between steps.", "New target: starts over at the first step. No live enemy selected, or yours just died: the press picks the nearest enemy first."}},
    {name = "Fight", title = "Fight (DoTs, Wrack, Drain Life)", icon = "ability_deathknight_hemorrhagicfever", lo = 40, hi = 60,
     body = "#showtooltip\n/targetenemy [noharm][dead]\n/petattack\n/castsequence [nochanneling:Drain Life/Drain Soul/Wrack/Health Funnel] reset=target Corruption, Bane of Agony, Siphon Life, Wrack, Drain Life, Drain Life", pad = "RT+A", kb = "1",
     tips = {"Each press: Corruption, Bane of Agony, Siphon Life, Wrack, Drain Life twice, then refresh.", "Wrack is a 6 sec channel: your other Shadow DoTs on the target take 10% more while it runs. Nightfall glow: Shadow Bolt from the spellbook is instant.", "Pressing while Drain Life, Wrack, Drain Soul or Health Funnel channels does nothing, so mash it. It does stop your wand, so wand between steps.", "New target: starts over at the first step. No live enemy selected, or yours just died: the press picks the nearest enemy first."}},
    {name = "Finisher", title = "Finisher (Drain Soul)", icon = "spell_shadow_haunting", lo = 10, hi = 60,
     body = "#showtooltip\n/cast [nochanneling:Drain Soul] Drain Soul", pad = "RT+B", kb = "2",
     tips = {"One press: Drain Soul, even in the middle of Drain Life or the wand (it stops them). Pressing again while Drain Soul channels does nothing, so it is never cut short.", "Start it when the mob is nearly dead: a mob worth experience that dies to it always gives a Soul Shard. Summons, Healthstones and Soulstones cost one each.", "Wrack and the drains can't be cut by Fight, so press this one when you want the shard."}},
    {name = "Wand", title = "Wand", icon = "inv_wand_01", lo = 1, hi = 60,
     body = "#showtooltip Shoot\n/targetenemy [noharm][dead]\n/petattack\n/cast [nochanneling:Shoot] Shoot", pad = "RT+Y", kb = "4",
     tips = {"Needs a wand. One press sends your demon and starts the wand on your target; pressing again while it shoots does not stop it.", "Let your DoTs tick and wand instead of casting: it costs no mana. Life Tap the mana back after the fight.", "No live enemy selected: the press picks the nearest one first."}},
    {name = "Pet", title = "Pet (summon / Health Funnel)", icon = "spell_shadow_summonvoidwalker", lo = 1, hi = 60,
     body = "#showtooltip\n/cast [nopet] Summon Voidwalker\n/cast [nopet] Summon Imp\n/cast [pet,nochanneling:Health Funnel] Health Funnel", pad = "LT+Y", kb = "F",
     tips = {"No demon out: summons your Voidwalker (level 10 class quest, costs a Soul Shard), else your Imp. A Felhunter (30) for caster areas comes from the spellbook.", "Demon out: Health Funnel heals it while you channel (12+); pressing again doesn't restart the channel.", "No Soul Shard: the summon line can't fire and the press stops there. Get shards with Drain Soul (RT+B), or summon the Imp from the spellbook."}},
    {name = "Healthstone", title = "Healthstone", icon = "inv_stone_04", lo = 10, hi = 60,
     body = "#showtooltip\n/use [combat] Major Healthstone\n/use [combat] Greater Healthstone\n/use [combat] Healthstone\n/use [combat] Lesser Healthstone\n/use [combat] Minor Healthstone\n/cast [nocombat] Create Healthstone", pad = "LT+B", kb = "E",
     tips = {"In combat: eats whichever Healthstone you carry (an item, no global cooldown); no need to rebind as the rank goes up.", "Out of combat: creates a new one (costs a Soul Shard). If you already carry one the game refuses to make another."}},
    {name = "Panic", title = "Panic (Death Coil, Healthstone)", icon = "spell_shadow_deathcoil", lo = 42, hi = 60,
     body = "#showtooltip Death Coil\n/stopcasting\n/cast Death Coil\n/use Major Healthstone\n/use Greater Healthstone\n/use Healthstone", pad = "LT+A", kb = "Q",
     tips = {"One press: stops your cast, Death Coil (the mob runs in horror for 3 sec and you heal for the damage dealt), then eats your Healthstone.", "While Death Coil cools (2 min) the press only stops your cast: use the Healthstone button (LT+B) then.", "Several mobs on you: Howl of Terror (40) from the spellbook, if there is room for them to run."}},
    {name = "Pet taunt", title = "Pet taunt", icon = "spell_shadow_gathershadows", lo = 10, hi = 35,
     body = "#showtooltip Torment\n/petattack\n/cast Torment", pad = "RT+Up", kb = "X",
     tips = {"One press: sends your demon at your target, and a Voidwalker also casts Torment to pull the mob off you.", "Other demons don't know Torment, so the line is skipped and the press just sends them in. Torment is the last line, so its cooldown blocks nothing.", "With a Felhunter out, this button casts Spell Lock from 36."}},
    {name = "Pet taunt", title = "Pet taunt / Spell Lock", icon = "spell_shadow_gathershadows", lo = 36, hi = 60,
     body = "#showtooltip\n/petattack\n/cast Torment\n/cast Spell Lock", pad = "RT+Up", kb = "X",
     tips = {"One press: sends your demon at your target. A Voidwalker also casts Torment to pull the mob off you.", "A Felhunter casts Spell Lock instead: it counters the target's spell and silences it. Press it as the cast starts.", "Each demon only knows its own spell, so the other line is skipped. Succubus or Imp: the press just sends them in."}},
  }, plan = {{name = "Improved Corruption", tree = "Affliction", from = 10, to = 14, why = "From 14 (5/5) Corruption is instant and hits 10% harder: cast it while running up, on every mob, to 60.", more = "Another 0.4 sec off Corruption.", max = 5, icon = "spell_shadow_abominationexplosion"}, {name = "Suppression", tree = "Affliction", from = 15, to = 17, why = "Every resisted DoT is wasted mana and a mob that reaches you sooner. Three points get you most of the way to never missing.", more = "+1% more hit.", max = 5, icon = "spell_shadow_unsummonbuilding"}, {name = "Improved Life Tap", tree = "Affliction", from = 18, to = 19, why = "Life Tap is your mana bar. 20% more mana per tap means fewer taps, less health to drain back.", more = "Life Tap gives another 10%.", max = 2, icon = "spell_shadow_burningspirit"}, {name = "Fel Concentration", tree = "Affliction", from = 20, to = 22, why = "The drain-tank talent. At 3/3, hits have a 70% chance not to push back Drain Life, so you can stand and drain through damage.", more = "More pushback protection.", max = 3, icon = "spell_shadow_fingerofdeath"}, {name = "Improved Drains", tree = "Affliction", from = 23, to = 25, why = "Drain Life, Drain Soul and Drain Mana do 7% more per point, 20% at 3/3. Drain Life lost 28% in Forever, so this keeps it useful.", more = "Drains 13%, then 20% stronger.", max = 3, icon = "spell_shadow_haunting"}, {name = "Nightfall", tree = "Affliction", from = 26, to = 27, why = "Corruption, drains and Wrack get a 2% chance per tick to make your next Shadow Bolt instant.", more = "Proc chance 4%.", max = 2, icon = "spell_shadow_twilight"}, {name = "Pandemic", tree = "Affliction", from = 28, to = 30, why = "DoT and drain crits get +33% bonus crit damage per point (+100% at 3/3) — more from spells you already cast.", more = "Bigger crit bonus.", max = 3, icon = "spell_shadow_unstableaffliction_2"}, {name = "Siphon Life", tree = "Affliction", from = 31, to = 31, why = "Instant 30 sec DoT that heals you 11 every 3 sec (41 at rank 4). Corruption + Agony + Siphon Life is the core setup and three effects for Soul Siphon.", more = "", max = 1, icon = "spell_shadow_requiem"}, {name = "Soul Siphon", tree = "Affliction", from = 32, to = 34, why = "Drain Life gets up to 36% stronger with your other effects on the target — so DoT first, then drain.", more = "+4% more per effect.", max = 3, icon = "spell_shadow_lifedrain02"}, {name = "Shadow Mastery", tree = "Affliction", from = 35, to = 39, why = "Every Shadow spell — Corruption, Agony, Siphon, Drain Life, Shadow Bolt — deals 10% more.", more = "+2% more Shadow damage.", max = 5, icon = "spell_shadow_shadetruesight"}, {name = "Wrack", tree = "Affliction", from = 40, to = 40, why = "The capstone: a 200-mana channel (86 Shadow per second at 60, buffed 2 Nov) that makes your other Shadow DoTs deal 10% more for 6 sec.", more = "", max = 1, icon = "ability_deathknight_hemorrhagicfever"}, {name = "Malevolence", tree = "Affliction", from = 41, to = 45, why = "+1% Shadow crit per point — more crits for Pandemic's +100% bonus.", more = "+1% more Shadow crit.", max = 5, icon = "spell_shadow_focusedpower"}, {name = "Improved Bane of Agony", tree = "Affliction", from = 46, to = 47, why = "Bane of Agony is on every target; 10% more is free damage.", more = "+5% more Agony damage.", max = 2, icon = "spell_shadow_curseofsargeras"}, {name = "Suppression", tree = "Affliction", from = 48, to = 49, why = "Higher-level mobs resist more. Suppression to 5/5 for 5% hit.", more = "+1% more hit.", max = 5, icon = "spell_shadow_unsummonbuilding"}, {name = "Grim Reach", tree = "Affliction", from = 50, to = 50, why = "Affliction spells reach 10% further — pull from safer distance.", more = "", max = 2, icon = "spell_shadow_callofbone"}, {name = "Unholy Power", tree = "Demonology", from = 51, to = 55, why = "Affliction is done. Your demon does a big share of your damage — 10% more from Unholy Power.", more = "+2% more demon damage.", max = 5, icon = "spell_shadow_shadowworddominate"}, {name = "Demonic Energies", tree = "Demonology", from = 56, to = 57, why = "Your spells now heal your demon, and Life Tap shares mana with it. Your Voidwalker barely needs Health Funnel.", more = "Pet healing doubled.", max = 2, icon = "spell_shadow_felmending"}, {name = "Fel Vitality", tree = "Demonology", from = 58, to = 60, why = "15% more health and mana for your demon, and 15% more mana for you.", more = "+5% more.", max = 3, icon = "spell_shadow_demonictactics"}}, train = {{level = 1, spells = {"Shadow Bolt (Rank 1)", "Immolate (Rank 1)", "Demon Skin (Rank 1)", "Summon Imp"}, notes = {"Opener early; Nightfall procs later.", "Fire DoT — good early, drop it if mana is tight once Siphon Life is up.", "Armor buff until Demon Armor.", "Your first demon."}, icons = {"spell_shadow_shadowbolt", "spell_fire_immolation", "spell_shadow_ragingscream", "spell_shadow_summonimp"}}, {level = 4, spells = {"Corruption (Rank 1)", "Curse of Weakness (Rank 1)"}, notes = {"Your core DoT.", "Less melee damage taken. Banes and Curses stack in Forever."}, icons = {"spell_shadow_abominationexplosion", "spell_shadow_curseofmannoroth"}}, {level = 6, spells = {"Life Tap (Rank 1)", "Shadow Bolt (Rank 2)"}, notes = {"Health into mana.", "Opener early; Nightfall procs later."}, icons = {"spell_shadow_burningspirit", "spell_shadow_shadowbolt"}}, {level = 8, spells = {"Bane of Agony (Rank 1)", "Fear (Rank 1)"}, notes = {"Your second DoT (was Curse of Agony).", "Only with open space — fleeing mobs pull friends."}, icons = {"spell_shadow_curseofsargeras", "spell_shadow_possession"}}, {level = 10, spells = {"Summon Voidwalker", "Drain Soul (Rank 1)", "Create Healthstone (Rank 1)", "Demon Skin (Rank 2)", "Immolate (Rank 2)"}, notes = {"From your level-10 class quest.", "Finisher — killing a non-trivial mob with it always gives a Soul Shard.", "Free emergency heal.", "Armor buff until Demon Armor.", "Fire DoT — good early, drop it if mana is tight once Siphon Life is up."}, icons = {"spell_shadow_summonvoidwalker", "spell_shadow_haunting", "inv_stone_04", "spell_shadow_ragingscream", "spell_fire_immolation"}}, {level = 12, spells = {"Health Funnel (Rank 1)", "Shadow Bolt (Rank 3)", "Curse of Weakness (Rank 2)"}, notes = {"Heal your demon.", "Opener early; Nightfall procs later.", "Less melee damage taken. Banes and Curses stack in Forever."}, icons = {"spell_shadow_lifedrain", "spell_shadow_shadowbolt", "spell_shadow_curseofmannoroth"}}, {level = 14, spells = {"Drain Life (Rank 1)", "Corruption (Rank 2)", "Curse of Recklessness (Rank 1)"}, notes = {"Your main channel and heal. 20 yd range, shorter than your DoTs.", "Your core DoT.", "Armor reduction; not for casters."}, icons = {"spell_shadow_lifedrain02", "spell_shadow_abominationexplosion", "spell_shadow_unholystrength"}}, {level = 16, spells = {"Life Tap (Rank 2)", "Unending Breath"}, notes = {"Health into mana.", "Underwater quests."}, icons = {"spell_shadow_burningspirit", "spell_shadow_demonbreath"}}, {level = 18, spells = {"Bane of Agony (Rank 2)", "Create Soulstone (Rank 1)", "Searing Pain (Rank 1)"}, notes = {"Your second DoT (was Curse of Agony).", "Self-res before risky pulls.", "Destruction filler."}, icons = {"spell_shadow_curseofsargeras", "spell_shadow_soulgem", "spell_fire_soulburn"}}, {level = 20, spells = {"Demon Armor (Rank 1)", "Shadow Bolt (Rank 4)", "Immolate (Rank 3)", "Health Funnel (Rank 2)", "Curse of the Elements (Rank 1)", "Summon Succubus", "Rain of Fire (Rank 1)", "Ritual of Summoning"}, notes = {"Replaces Demon Skin.", "Opener early; Nightfall procs later.", "Fire DoT — good early, drop it if mana is tight once Siphon Life is up.", "Heal your demon.", "+Magic damage taken — worth it on long fights, alongside your Bane.", "Class quest. Incubus is the same demon.", "AoE in groups.", "Summon friends."}, icons = {"spell_shadow_ragingscream", "spell_shadow_shadowbolt", "spell_fire_immolation", "spell_shadow_lifedrain", "warlock_curse_shadow", "spell_s